export interface ToolDefinition {
    standard?: number; // months
    partial?: number; // months
    full?: number; // months
    details?: string[];
}

export interface ToolDefinitions {
    [tipo: string]: {
        [herramienta: string]: ToolDefinition;
    };
}

import type { Tool, Status, Personnel } from '../types';
import { TOOL_DEFINITIONS } from '../definitions';

export const calculateNextInspection = (tool: Omit<Tool, 'nextInspectionDate' | 'status'>): Date | null => {
    if (!tool.ultimaInspeccion) return null;
    const lastDate = new Date(tool.ultimaInspeccion + 'T00:00:00');
    if (isNaN(lastDate.getTime())) return null;

    const definition = TOOL_DEFINITIONS[tool.tipo]?.[tool.herramienta];
    if (!definition) return null;

    let monthsToAdd = 0;
    if (definition.standard) {
        monthsToAdd = definition.standard;
    } else if (definition.partial && definition.full) {
        monthsToAdd = tool.tipoUltimaInspeccion === 'Full' ? definition.full : definition.partial;
    }

    if (monthsToAdd > 0) {
        lastDate.setMonth(lastDate.getMonth() + monthsToAdd);
        return lastDate;
    }
    return null;
}

export const getStatus = (nextInspectionDate: Date | null): Status => {
    if (!nextInspectionDate) return { text: 'N/A', color: 'gray' };

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const thirtyDaysFromNow = new Date();
    thirtyDaysFromNow.setDate(today.getDate() + 30);
    thirtyDaysFromNow.setHours(0,0,0,0);

    if (nextInspectionDate < today) {
        return { text: 'Vencida', color: 'red' };
    } else if (nextInspectionDate <= thirtyDaysFromNow) {
        return { text: 'Por Vencer', color: 'yellow' };
    } else {
        return { text: 'Vigente', color: 'green' };
    }
}

export const getDaysUntilExpiry = (nextInspectionDate: Date | null): number | null => {
    if (!nextInspectionDate) return null;

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const expiryDate = new Date(nextInspectionDate);
    expiryDate.setHours(0, 0, 0, 0);

    if (expiryDate < today) return 0;

    const diffTime = expiryDate.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    return diffDays;
}

export const isNotificationActive = (tool: Tool): boolean => {
    // The bell is visually active if the tool's inspection is expired or expiring soon (within 30 days).
    return tool.status.text === 'Vencida' || tool.status.text === 'Por Vencer';
}

export const calculateAge = (dob: string): number | null => {
    if (!dob) return null;
    const birthDate = new Date(dob);
    if (isNaN(birthDate.getTime())) return null;

    const today = new Date();
    let age = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();

    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
        age--;
    }

    return age;
};

export const calculateDiagramStatus = (startDateStr: string | undefined, diagramType?: Personnel['diagramType']): string => {
    if (!startDateStr) {
        return 'N/A';
    }

    const startDate = new Date(startDateStr + 'T00:00:00');
    if (isNaN(startDate.getTime())) {
        return 'Fecha Inválida';
    }

    let workDays = 10;
    let cycleLength = 15; // Default 10x5

    if (diagramType === '5x2') {
        workDays = 5;
        cycleLength = 7;
    } else if (diagramType === '8x4') {
        workDays = 8;
        cycleLength = 12;
    }

    const today = new Date();
    today.setHours(0, 0, 0, 0);
    startDate.setHours(0, 0, 0, 0);

    const diffTime = today.getTime() - startDate.getTime();
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

    const dayInCycle = (diffDays % cycleLength) + 1;

    if (dayInCycle <= workDays) {
        return `Día ${dayInCycle} de diagrama`;
    } else {
        return 'Franco';
    }
};

export const getDiagramDayStatus = (startDateStr: string | undefined, targetDate: Date, diagramType?: Personnel['diagramType']): 'Work' | 'Franco' | 'Invalid' | 'N/A' => {
    if (!startDateStr) {
        return 'N/A';
    }

    const startDate = new Date(startDateStr + 'T00:00:00');
    if (isNaN(startDate.getTime())) {
        return 'Invalid';
    }

    let workDays = 10;
    let cycleLength = 15; // Default 10x5

    if (diagramType === '5x2') {
        workDays = 5;
        cycleLength = 7;
    } else if (diagramType === '8x4') {
        workDays = 8;
        cycleLength = 12;
    }

    const currentTargetDate = new Date(targetDate);
    currentTargetDate.setHours(0, 0, 0, 0);
    startDate.setHours(0, 0, 0, 0);

    const diffTime = currentTargetDate.getTime() - startDate.getTime();
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

    const dayInCycle = (((diffDays % cycleLength) + cycleLength) % cycleLength) + 1;

    if (dayInCycle <= workDays) {
        return 'Work';
    } else {
        return 'Franco';
    }
};

export const getPersonnelCourseStatus = (personnel: Personnel): Status => {
    if (!personnel.courses || personnel.courses.length === 0) {
        return { text: 'Vigente', color: 'green' };
    }

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const thirtyDaysFromNow = new Date();
    thirtyDaysFromNow.setDate(today.getDate() + 30);
    thirtyDaysFromNow.setHours(0, 0, 0, 0);

    let isExpiringSoon = false;

    for (const course of personnel.courses) {
        if (!course.expiryDate) continue;
        const expiryDate = new Date(course.expiryDate + 'T00:00:00');
        if (isNaN(expiryDate.getTime())) continue;

        if (expiryDate < today) {
            return { text: 'Vencida', color: 'red' }; // Most urgent
        }

        if (expiryDate <= thirtyDaysFromNow) {
            isExpiringSoon = true;
        }
    }

    if (isExpiringSoon) {
        return { text: 'Por Vencer', color: 'yellow' };
    }

    return { text: 'Vigente', color: 'green' };
};

import React, { useState, useEffect, useMemo } from 'react';
import type { Personnel, Course, PersonnelCourse, PersonnelEvent, PersonnelEventType } from '../types';
import { PERSONNEL_SECTORS } from '../definitions';
import { calculateAge } from '../utils/dateUtils';
import { TrashIcon, PlusIcon } from './icons';
import Modal from './Modal';

interface PersonnelFormModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSave: (personnel: Personnel) => void;
    onDelete: (personnelId: string) => void;
    editingPersonnel: Personnel | null;
    coursesList: Course[];
}

const PersonnelFormModal: React.FC<PersonnelFormModalProps> = ({ isOpen, onClose, onSave, onDelete, editingPersonnel, coursesList }) => {
    const [formData, setFormData] = useState<Omit<Personnel, 'id'>>({
        firstName: '', lastName: '', dob: '', sector: 'Mantenimiento', courses: [], diagramStartDate: '', diagramType: null, events: []
    });
    const [newCourse, setNewCourse] = useState<{ courseId: string; issueDate: string; expiryDate: string }>({
        courseId: '', issueDate: '', expiryDate: ''
    });
    const [newEvent, setNewEvent] = useState<{ type: Exclude<PersonnelEventType, 'Franco'>; startDate: string; endDate: string }>({
        type: 'Vacaciones', startDate: '', endDate: ''
    });


    useEffect(() => {
        if (isOpen) {
            if (editingPersonnel) {
                setFormData({ ...editingPersonnel });
            } else {
                setFormData({ firstName: '', lastName: '', dob: '', sector: 'Mantenimiento', courses: [], diagramStartDate: '', diagramType: null, events: [] });
            }
            setNewCourse({ courseId: '', issueDate: '', expiryDate: '' });
            setNewEvent({ type: 'Vacaciones', startDate: '', endDate: '' });
        }
    }, [isOpen, editingPersonnel]);

    const age = useMemo(() => calculateAge(formData.dob), [formData.dob]);
    const getCourseName = (id: string) => coursesList.find(c => c.id === id)?.name || 'Desconocido';

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => {
            const newState = { ...prev, [name]: value };
            // If sector is changed to something other than Jerarquico, clear diagram type
            if (name === 'sector' && value !== 'Jerarquico') {
                newState.diagramType = null;
            }
             // If sector is changed to Jerarquico, set a default diagram type
            if (name === 'sector' && value === 'Jerarquico') {
                newState.diagramType = prev.diagramType || '10x5';
            }
            return newState;
        });
    };

    const handleCourseChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setNewCourse(prev => ({ ...prev, [name]: value }));
    };

    const handleNewEventChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setNewEvent(prev => ({ ...prev, [name]: value }));
    };

    const handleAddCourse = () => {
        if (newCourse.courseId && newCourse.issueDate && newCourse.expiryDate && !formData.courses.some(c => c.courseId === newCourse.courseId)) {
            setFormData(prev => ({ ...prev, courses: [...prev.courses, { ...newCourse }] }));
            setNewCourse({ courseId: '', issueDate: '', expiryDate: '' });
        }
    };

    const handleAddEvent = () => {
        if (newEvent.startDate && newEvent.endDate && newEvent.startDate <= newEvent.endDate) {
            setFormData(prev => ({
                ...prev,
                events: [...prev.events, { ...newEvent, id: new Date().toISOString() }]
            }));
            setNewEvent({ type: 'Vacaciones', startDate: '', endDate: '' });
        } else {
