import React, { useState } from 'react';
import type { Operation, Tool, Role } from '../types';
import { TimesIcon, ChevronDownIcon, ChevronUpIcon } from './icons';

interface OperationCardProps {
    operation: Operation;
    assignedToolsData: Tool[];
    onDropTool: (operationId: string, toolId: string) => void;
    onRemoveTool: (operationId: string, toolId: string) => void;
    userRole: Role | null;
    isExpanded: boolean;
    onToggleExpansion: () => void;
}

const OperationCard: React.FC<OperationCardProps> = ({ operation, assignedToolsData, onDropTool, onRemoveTool, userRole, isExpanded, onToggleExpansion }) => {
    const [isDragOver, setIsDragOver] = useState(false);

    const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        if (userRole === 'Admin') {
            setIsDragOver(true);
        }
    };

    const handleDragLeave = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        setIsDragOver(false);
    };

    const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        setIsDragOver(false);
        if (userRole !== 'Admin') return;

        const toolId = e.dataTransfer.getData('text/plain');
        if (toolId) {
            onDropTool(operation.id, toolId);
        }
    };

    const cardClasses = [
        'bg-white dark:bg-gray-800 rounded-lg shadow-md p-4 flex flex-col h-full border-2',
        isDragOver ? 'border-blue-500 border-dashed' : 'border-transparent'
    ].join(' ');

    const getStatusChipClass = (estado: string) => {
        switch(estado) {
            case 'Operando': return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300';
            case 'Programada': return 'bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-300';
            case 'Terminaron': return 'bg-gray-100 text-gray-800 dark:bg-gray-600 dark:text-gray-200';
            case 'Op. Cancelada': return 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300';
            default: return 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-300';
        }
    };

    return (
        <div 
            className={cardClasses}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
        >
            <div className="flex-shrink-0 mb-3 border-b border-gray-200 dark:border-gray-700 pb-3">
                <div className="flex justify-between items-start mb-1">
                    <h3 className="font-bold text-lg text-gray-800 dark:text-gray-100">
                        {operation.equipo}
                        <span className="ml-2 text-sm font-medium text-gray-500 dark:text-gray-400">({assignedToolsData.length})</span>
                    </h3>
                    <span className={`text-xs font-semibold px-2 py-0.5 rounded-full ${getStatusChipClass(operation.estado)}`}>
                        {operation.estado}
                    </span>
                </div>
                <p className="text-sm text-gray-500 dark:text-gray-400">{operation.operadora} - {operation.yacimiento}</p>
                <span className="text-xs font-mono bg-gray-100 dark:bg-gray-700 px-2 py-0.5 rounded-full">{operation.solicitud}</span>
            </div>

            <div className="flex-grow min-h-[100px] mb-3">
                <div className="flex justify-between items-center mb-2">
                    <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300">Herramientas Asignadas:</h4>
                    {assignedToolsData.length > 0 && (
                        <button
                            onClick={onToggleExpansion}
                            className="p-1 text-gray-500 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition"
                            title={isExpanded ? "Ocultar herramientas" : "Mostrar herramientas"}
                        >
                            {isExpanded ? <ChevronUpIcon /> : <ChevronDownIcon />}
                        </button>
                    )}
                </div>

                {assignedToolsData.length > 0 ? (
                    <div className={`transition-all duration-300 ease-in-out overflow-hidden ${isExpanded ? 'max-h-[500px]' : 'max-h-0'}`}>
                        <ul className="space-y-2 pt-1">
                            {assignedToolsData.map(tool => {
                                const borderColorClass = {
                                    red: 'border-red-500',
                                    yellow: 'border-yellow-500',
                                    green: 'border-green-500',
                                    gray: 'border-gray-400 dark:border-gray-500',
                                }[tool.status.color];

                                return (
                                    <li key={tool.id} className={`bg-gray-50 dark:bg-gray-700/50 p-2 rounded-md flex items-center text-sm border-l-4 ${borderColorClass} space-x-2`}>
                                        <div className="flex-grow">
                                            <p className="font-medium text-gray-800 dark:text-gray-200">{tool.herramienta}</p>
                                            <p className="text-xs text-gray-500 dark:text-gray-400 font-mono">{tool.serial}</p>
                                        </div>
                                        <div className="text-right flex-shrink-0">
                                            <p className="text-xs font-semibold text-gray-700 dark:text-gray-300">
                                                {tool.nextInspectionDate ? tool.nextInspectionDate.toLocaleDateString('es-ES') : 'N/A'}
                                            </p>
                                        </div>
                                        {userRole === 'Admin' && (
                                            <button 
                                                onClick={() => onRemoveTool(operation.id, tool.id)}
                                                className="text-red-500 hover:text-red-700 dark:text-red-400 dark:hover:text-red-300 flex-shrink-0"
                                                title="Liberar herramienta"
                                            >
                                                <TimesIcon />
                                            </button>
                                        )}
                                    </li>
                                );
                            })}
                        </ul>
                    </div>
                ) : (
                    <div className="flex items-center justify-center h-full text-gray-400 dark:text-gray-500 text-sm">
                        <p>Arrastra una herramienta aquí</p>
                    </div>
                )}
            </div>

            <div className="flex-shrink-0 text-xs text-gray-500 dark:text-gray-400 mt-auto pt-2 border-t border-gray-200 dark:border-gray-700 space-y-1">
                <p><strong>Tipo:</strong> {operation.tipoOperacion}</p>
                <p><strong>Fechas:</strong> {(operation.fechaInicio && operation.fechaFin) ? `${operation.fechaInicio} al ${operation.fechaFin}` : (operation.fechaInicio || operation.fechaFin || 'N/A')}</p>
                {operation.buidsheet && <p><strong>Buidsheet:</strong> {operation.buidsheet}</p>}
                {operation.DT && <p><strong>DT:</strong> {operation.DT}</p>}
            </div>
        </div>
    );
};

export default OperationCard;

import type { Tool } from '../types';

export const generatePDFReport = (tools: Tool[]) => {
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF();
    const toolsToReport = tools.filter(tool => tool.status.text === 'Vencida' || tool.status.text === 'Por Vencer');

    // Sort tools: 'Vencida' first, then 'Por Vencer'.
    // Within each group, sort by the nearest expiration date.
    const statusOrder: { [key: string]: number } = { 'Vencida': 1, 'Por Vencer': 2 };

    toolsToReport.sort((a, b) => {
        const orderA = statusOrder[a.status.text] || 3;
        const orderB = statusOrder[b.status.text] || 3;
        if (orderA !== orderB) {
            return orderA - orderB;
        }
        const dateA = a.nextInspectionDate?.getTime() || 0;
        const dateB = b.nextInspectionDate?.getTime() || 0;
        return dateA - dateB; // Sort by earliest date
    });

    const tableColumn = ["Herramienta", "Serial", "Estado", "Fecha de Vencimiento"];
    const tableRows = toolsToReport.map(tool => [
        `${tool.herramienta} ${tool.detalle || ''}`.trim(),
        tool.serial,
        tool.status.text,
        tool.nextInspectionDate ? tool.nextInspectionDate.toLocaleDateString('es-ES') : 'N/A'
    ]);

    const reportDate = new Date().toLocaleDateString('es-ES');

    // Using declare to assert the type of autoTable
    (doc as any).autoTable({ 
        head: [tableColumn], 
        body: tableRows, 
        startY: 30, // Increased startY to avoid overlap with header
        theme: 'grid', 
        headStyles: { fillColor: [22, 160, 133] },
        didDrawPage: (data: any) => {
            // Header for every page
            doc.setFontSize(11);
            doc.setTextColor(100);
            doc.text(`Fecha: ${reportDate}`, 14, 10);

            doc.setFontSize(18);
            doc.setTextColor(0);
            doc.setFont('helvetica', 'bold');
            doc.text("Informe de Inspecciones", 14, 22);

            // Optional: Footer with page number
            const str = "Página " + doc.internal.getNumberOfPages();
            doc.setFontSize(10);
            doc.setTextColor(150);
            const pageSize = doc.internal.pageSize;
            const pageHeight = pageSize.height ? pageSize.height : pageSize.getHeight();
            doc.text(str, data.settings.margin.left, pageHeight - 10);
        }
    });

    doc.save(`informe_inspecciones_${reportDate.replace(/\//g, '-')}.pdf`);
};

