import React, { useState } from 'react';
import type { Operation, Tool, Role } from '../types';
import { TimesIcon, ChevronDownIcon, ChevronUpIcon } from './icons';

interface OperationCardProps {
    operation: Operation;
    assignedToolsData: Tool[];
    onDropTool: (operationId: string, toolId: string) => void;
    onRemoveTool: (operationId: string, toolId: string) => void;
    userRole: Role | null;
    isExpanded: boolean;
    onToggleExpansion: () => void;
}

const OperationCard: React.FC<OperationCardProps> = ({ operation, assignedToolsData, onDropTool, onRemoveTool, userRole, isExpanded, onToggleExpansion }) => {
    const [isDragOver, setIsDragOver] = useState(false);

    const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        if (userRole === 'Admin') {
            setIsDragOver(true);
        }
    };

    const handleDragLeave = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        setIsDragOver(false);
    };

    const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        setIsDragOver(false);
        if (userRole !== 'Admin') return;

        const toolId = e.dataTransfer.getData('text/plain');
        if (toolId) {
            onDropTool(operation.id, toolId);
        }
    };

    const cardClasses = [
        'bg-white dark:bg-gray-800 rounded-lg shadow-md p-4 flex flex-col h-full border-2',
        isDragOver ? 'border-blue-500 border-dashed' : 'border-transparent'
    ].join(' ');

    const getStatusChipClass = (estado: string) => {
        switch(estado) {
            case 'Operando': return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300';
            case 'Programada': return 'bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-300';
            case 'Terminaron': return 'bg-gray-100 text-gray-800 dark:bg-gray-600 dark:text-gray-200';
            case 'Op. Cancelada': return 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300';
            default: return 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-300';
        }
    };

    return (
        <div 
            className={cardClasses}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
        >
            <div className="flex-shrink-0 mb-3 border-b border-gray-200 dark:border-gray-700 pb-3">
                <div className="flex justify-between items-start mb-1">
                    <h3 className="font-bold text-lg text-gray-800 dark:text-gray-100">
                        {operation.equipo}
                        <span className="ml-2 text-sm font-medium text-gray-500 dark:text-gray-400">({assignedToolsData.length})</span>
                    </h3>
                    <span className={`text-xs font-semibold px-2 py-0.5 rounded-full ${getStatusChipClass(operation.estado)}`}>
                        {operation.estado}
                    </span>
                </div>
                <p className="text-sm text-gray-500 dark:text-gray-400">{operation.operadora} - {operation.yacimiento}</p>
                <span className="text-xs font-mono bg-gray-100 dark:bg-gray-700 px-2 py-0.5 rounded-full">{operation.solicitud}</span>
            </div>

            <div className="flex-grow min-h-[100px] mb-3">
                <div className="flex justify-between items-center mb-2">
                    <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300">Herramientas Asignadas:</h4>
                    {assignedToolsData.length > 0 && (
                        <button
                            onClick={onToggleExpansion}
                            className="p-1 text-gray-500 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition"
                            title={isExpanded ? "Ocultar herramientas" : "Mostrar herramientas"}
                        >
                            {isExpanded ? <ChevronUpIcon /> : <ChevronDownIcon />}
                        </button>
                    )}
                </div>

                {assignedToolsData.length > 0 ? (
                    <div className={`transition-all duration-300 ease-in-out ${isExpanded ? 'max-h-64 overflow-y-auto custom-scrollbar' : 'max-h-0 overflow-hidden'}`}>
                        <ul className="space-y-2 pt-1 pr-2">
                            {assignedToolsData.map(tool => {
                                const borderColorClass = {
                                    red: 'border-red-500',
                                    yellow: 'border-yellow-500',
                                    green: 'border-green-500',
                                    gray: 'border-gray-400 dark:border-gray-500',
                                }[tool.status.color];

                                return (
                                    <li key={tool.id} className={`bg-gray-50 dark:bg-gray-700/50 p-2 rounded-md flex items-center text-sm border-l-4 ${borderColorClass} space-x-2`}>
                                        <div className="flex-grow">
                                            <p className="font-medium text-gray-800 dark:text-gray-200">{tool.herramienta}</p>
                                            <p className="text-xs text-gray-500 dark:text-gray-400 font-mono">{tool.serial}</p>
                                        </div>
                                        <div className="text-right flex-shrink-0">
                                            <p className="text-xs font-semibold text-gray-700 dark:text-gray-300">
                                                {tool.nextInspectionDate ? tool.nextInspectionDate.toLocaleDateString('es-ES') : 'N/A'}
                                            </p>
                                        </div>
                                        {userRole === 'Admin' && (
                                            <button 
                                                onClick={() => onRemoveTool(operation.id, tool.id)}
                                                className="text-red-500 hover:text-red-700 dark:text-red-400 dark:hover:text-red-300 flex-shrink-0"
                                                title="Liberar herramienta"
                                            >
                                                <TimesIcon />
                                            </button>
                                        )}
                                    </li>
                                );
                            })}
                        </ul>
                    </div>
                ) : (
                    <div className="flex items-center justify-center h-full text-gray-400 dark:text-gray-500 text-sm">
                        <p>Arrastra una herramienta aquí</p>
                    </div>
                )}
            </div>

            <div className="flex-shrink-0 text-xs text-gray-500 dark:text-gray-400 mt-auto pt-2 border-t border-gray-200 dark:border-gray-700 space-y-1">
                <p><strong>Tipo:</strong> {operation.tipoOperacion}</p>
                <p><strong>Fechas:</strong> {(operation.fechaInicio && operation.fechaFin) ? `${operation.fechaInicio} al ${operation.fechaFin}` : (operation.fechaInicio || operation.fechaFin || 'N/A')}</p>
                {operation.buidsheet && <p><strong>Buidsheet:</strong> {operation.buidsheet}</p>}
                {operation.DT && <p><strong>DT:</strong> {operation.DT}</p>}
            </div>
        </div>
    );
};

export default OperationCard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import type { Personnel, PersonnelEvent, Role } from '../types';
import { getDiagramDayStatus } from '../utils/dateUtils';
import { SearchIcon, PencilIcon, ChevronLeftIcon, ChevronRightIcon } from '../components/icons';

interface DiagramaViewProps {
    personnel: Personnel[];
    handleOpenPersonnelForm: (personnel: Personnel | null) => void;
    userRole: Role | null;
}

const EVENT_STYLES: { [key in Exclude<PersonnelEvent['type'], 'Franco'>]: string } = {
    'Operación': 'bg-orange-500 text-white',
    'Vacaciones': 'bg-green-500 text-white',
    'Compensatorio': 'bg-yellow-500 text-black',
    'Enfermedad': 'bg-purple-500 text-white',
};
const FRANCO_STYLE = 'bg-blue-600 text-white';

const DiagramaView: React.FC<DiagramaViewProps> = ({ personnel, handleOpenPersonnelForm, userRole }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [viewDate, setViewDate] = useState(new Date());
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const todayCellRef = useRef<HTMLTableCellElement>(null);

    const handlePreviousMonth = () => {
        setViewDate(current => new Date(current.getFullYear(), current.getMonth() - 1, 1));
    };

    const handleNextMonth = () => {
        setViewDate(current => new Date(current.getFullYear(), current.getMonth() + 1, 1));
    };

    const dates = useMemo(() => {
        const dateArray: Date[] = [];
        const year = viewDate.getFullYear();
        const month = viewDate.getMonth();
        const daysInMonth = new Date(year, month + 1, 0).getDate();

        for (let i = 1; i <= daysInMonth; i++) {
            dateArray.push(new Date(year, month, i));
        }
        return dateArray;
    }, [viewDate]);

    // Effect to scroll to today's date on mount and month change
    useEffect(() => {
        if (todayCellRef.current && scrollContainerRef.current) {
            const container = scrollContainerRef.current;
            const todayCell = todayCellRef.current;

            const containerWidth = container.clientWidth;
            const todayCellLeft = todayCell.offsetLeft;
            const todayCellWidth = todayCell.offsetWidth;

            // Calculate the scroll position to center the cell
            const scrollLeft = todayCellLeft - (containerWidth / 2) + (todayCellWidth / 2);

            container.scrollLeft = scrollLeft;
        }
    }, [dates]); // Re-run when the month (and thus the dates array) changes

    const filteredPersonnel = useMemo(() => {
        return personnel.filter(p =>
            `${p.firstName} ${p.lastName}`.toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [personnel, searchTerm]);

    const groupedPersonnel = useMemo(() => {
        const groups: { [key: string]: Personnel[] } = {};

        filteredPersonnel.forEach(p => {
            let key = p.sector || 'Sin Sector';
            if (p.sector === 'Jerarquico') {
                key = `Jerarquico (${p.diagramType || '10x5'})`;
            }

            if (!groups[key]) {
                groups[key] = [];
            }
            groups[key].push(p);
        });

        const customPersonnelOrder: { [key: string]: number } = {
            // ODS Sector
            'Martínez, Eric': 1,
            'Maldonado, Nicolas': 2,
            'Huenchupan, Daian': 3,
            // Laboratorio Sector
            'Furlon, Jonatan': 1,
            'Canosa, Gonzalo': 2,
        };

        for (const sector in groups) {
            groups[sector].sort((a, b) => {
                const nameA = `${a.lastName}, ${a.firstName}`;
                const nameB = `${b.lastName}, ${b.firstName}`;

                const orderA = customPersonnelOrder[nameA];
                const orderB = customPersonnelOrder[nameB];

                if (orderA !== undefined && orderB !== undefined) {
                    return orderA - orderB;
                }
                if (orderA !== undefined) return -1;
                if (orderB !== undefined) return 1;

                return nameA.localeCompare(nameB);
            });
        }

        const sectorOrder = ['ODS', 'Convencional', 'Mantenimiento', 'Laboratorio', 'Jerarquico (10x5)', 'Jerarquico (5x2)', 'Sin Sector'];

        return Object.entries(groups).sort((a, b) => {
            const indexA = sectorOrder.indexOf(a[0]);
            const indexB = sectorOrder.indexOf(b[0]);
            const finalIndexA = indexA === -1 ? Infinity : indexA;
            const finalIndexB = indexB === -1 ? Infinity : indexB;
            return finalIndexA - finalIndexB;
        });
    }, [filteredPersonnel]);

    const getCellContent = (person: Personnel, date: Date) => {
        const dateStr = date.toISOString().split('T')[0];

        for (const event of person.events) {
            if (dateStr >= event.startDate && dateStr <= event.endDate) {
                return { text: event.type.charAt(0).toUpperCase(), style: EVENT_STYLES[event.type], title: event.type };
            }
        }

        const diagramStatus = getDiagramDayStatus(person.diagramStartDate, date, person.diagramType);
        if (diagramStatus === 'Franco') {
            return { text: 'F', style: FRANCO_STYLE, title: 'Franco' };
        }

        return { text: '', style: 'bg-white dark:bg-gray-800', title: 'Día de diagrama' };
    };

    const isToday = (date: Date) => {
        const today = new Date();
        return date.getDate() === today.getDate() &&
               date.getMonth() === today.getMonth() &&
               date.getFullYear() === today.getFullYear();
    };

    return (
        <div className="p-4 h-full flex flex-col overflow-hidden bg-gray-50 dark:bg-gray-900">
            <header className="flex flex-col sm:flex-row justify-between sm:items-center mb-4 flex-shrink-0 gap-4">
                <div className="flex items-center gap-4">
                    <h1 className="text-2xl font-bold">Diagrama de Personal R&M</h1>
                    <div className="flex items-center gap-2 bg-white dark:bg-gray-800 p-1 rounded-lg border border-gray-200 dark:border-gray-700 shadow-sm">
                        <button onClick={handlePreviousMonth} className="p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700" aria-label="Mes anterior">
                            <ChevronLeftIcon />
                        </button>
                        <span className="font-semibold w-32 text-center capitalize">
                            {viewDate.toLocaleString('es-ES', { month: 'long', year: 'numeric' })}
                        </span>
                        <button onClick={handleNextMonth} className="p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700" aria-label="Mes siguiente">
                            <ChevronRightIcon />
                        </button>
                    </div>
                </div>
                <div className="flex items-center gap-4 flex-wrap">
                    <div className="relative">
                        <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Buscar persona..." className="w-full sm:w-64 p-2 pl-10 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500" />
                        <div className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"><SearchIcon /></div>
                    </div>
                    <div className="flex items-center gap-x-3 gap-y-1 text-xs flex-wrap">
                        <span className="flex items-center gap-1"><span className="h-3 w-3 bg-orange-500 rounded-sm"></span>O: Operación</span>
                        <span className="flex items-center gap-1"><span className="h-3 w-3 bg-blue-600 rounded-sm"></span>F: Franco</span>
                        <span className="flex items-center gap-1"><span className="h-3 w-3 bg-green-500 rounded-sm"></span>V: Vacaciones</span>
                        <span className="flex items-center gap-1"><span className="h-3 w-3 bg-yellow-500 rounded-sm"></span>C: Compensatorio</span>
                        <span className="flex items-center gap-1"><span className="h-3 w-3 bg-purple-500 rounded-sm"></span>E: Enfermedad</span>
                    </div>
                </div>
            </header>

            <div ref={scrollContainerRef} className="flex-grow overflow-auto custom-scrollbar border border-gray-200 dark:border-gray-700 rounded-lg shadow-md">
                <table className="min-w-full text-center text-xs border-collapse">
                    <thead className="sticky top-0 bg-gray-100 dark:bg-gray-800 z-10 shadow-sm">
                        <tr>
                            <th className="sticky left-0 bg-gray-100 dark:bg-gray-800 p-2 border-r border-b border-gray-200 dark:border-gray-700 min-w-[200px] z-20">Apellido y Nombre</th>
                            {dates.map(date => (
                                <th 
                                    key={date.toISOString()}
                                    ref={isToday(date) ? todayCellRef : null}
                                    className={`p-1 border-b border-l border-gray-200 dark:border-gray-700 min-w-[40px] ${isToday(date) ? 'bg-red-500 text-white' : ''}`}>
                                    <div>{['D', 'L', 'M', 'M', 'J', 'V', 'S'][date.getDay()]}</div>
                                    <div className="font-bold text-base">{date.getDate()}</div>
                                </th>
                            ))}
                        </tr>
                    </thead>
                    <tbody>
                        {groupedPersonnel.map(([groupName, people]) => (
                            <React.Fragment key={groupName}>
                                <tr className="bg-gray-200 dark:bg-gray-700/80">
                                    <td colSpan={dates.length + 1} className="sticky left-0 text-left p-1 pl-4 font-semibold text-gray-600 dark:text-gray-300 bg-gray-200 dark:bg-gray-700/80 border-r border-gray-200 dark:border-gray-700">
                                        Sector: {groupName}
                                    </td>
                                </tr>
                                {people.map(person => (
                                    <tr key={person.id} className="group">
                                        <td className="sticky left-0 bg-white dark:bg-gray-800 group-hover:bg-gray-50 dark:group-hover:bg-gray-700/50 p-2 border-r border-b border-gray-200 dark:border-gray-700 text-left font-medium flex justify-between items-center z-10">
                                            <span>{person.lastName}, {person.firstName}</span>
                                            {userRole === 'Admin' && (
                                                <button onClick={() => handleOpenPersonnelForm(person)} className="text-gray-400 hover:text-blue-500 text-xs opacity-0 group-hover:opacity-100 transition-opacity"> <PencilIcon/> </button>
                                            )}
                                        </td>
                                        {dates.map(date => {
                                            const cell = getCellContent(person, date);
                                            return (
                                                <td key={date.toISOString()} title={cell.title} className={`p-2 border-b border-l border-gray-200 dark:border-gray-700 font-bold transition-colors ${cell.style} ${isToday(date) ? 'outline outline-1 outline-red-500 -outline-offset-1' : ''}`}>
                                                    {cell.text}
                                                </td>
                                            );
                                        })}
                                    </tr>
                                ))}
                            </React.Fragment>
                        ))}
                    </tbody>
                </table>
                 {groupedPersonnel.length === 0 && (
                    <div className="p-8 text-center text-gray-500">No se encontró personal con los filtros aplicados.</div>
                 )}
            </div>
        </div>
    );
};
export default DiagramaView;

import React, { useState, useMemo, useEffect } from 'react';
import type { Tool, Role } from '../types';
import { generatePDFReport } from '../services/reportService';
import { PlusIcon, PencilIcon, TrashIcon, PdfIcon, SearchIcon, ChevronDownIcon, ChevronRightIcon } from '../components/icons';

interface ToolManagementViewProps {
    tools: Tool[];
    handleOpenToolForm: (tool: Tool | null) => void;
    handleDeleteTool: (toolId: string) => void;
    userRole: Role | null;
}

const ToolManagementView: React.FC<ToolManagementViewProps> = ({ tools, handleOpenToolForm, handleDeleteTool, userRole }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());

    const filteredTools = useMemo(() => {
        if (!searchTerm) {
            return tools;
        }
        return tools.filter(tool =>
            tool.serial.toLowerCase().includes(searchTerm.toLowerCase()) ||
            tool.herramienta.toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [tools, searchTerm]);

    const groupedTools = useMemo(() => {
        const groups: { [key: string]: Tool[] } = {};
        filteredTools.forEach(tool => {
            const key = tool.herramienta;
            if (!groups[key]) {
                groups[key] = [];
            }
            groups[key].push(tool);
        });

        // Sort groups alphabetically
        return Object.keys(groups).sort().reduce((obj, key) => {
            obj[key] = groups[key];
            return obj;
        }, {} as { [key: string]: Tool[] });
    }, [filteredTools]);

    // Automatically expand groups when searching so the user sees the results immediately
    useEffect(() => {
        if (searchTerm) {
            setExpandedGroups(new Set(Object.keys(groupedTools)));
        }
    }, [searchTerm, groupedTools]);

    const toggleGroup = (groupName: string) => {
        setExpandedGroups(prev => {
            const next = new Set(prev);
            if (next.has(groupName)) {
                next.delete(groupName);
            } else {
                next.add(groupName);
            }
            return next;
        });
    };

    const getStatusChipClass = (status: Tool['status']) => {
        switch(status.color) {
            case 'green': return 'bg-green-100 text-green-800 dark:bg-green-900/40 dark:text-green-300';
            case 'yellow': return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/40 dark:text-yellow-300';
            case 'red': return 'bg-red-100 text-red-800 dark:bg-red-900/40 dark:text-red-300';
            default: return 'bg-gray-100 text-gray-800 dark:bg-gray-600 dark:text-gray-200';
        }
    };

    const formatDate = (dateString: string) => {
        if (!dateString) return 'N/A';
        try {
            const [year, month, day] = dateString.split('-');
            if (!year || !month || !day) return dateString;
            return `${day}/${month}/${year}`;
        } catch (e) {
            return dateString;
        }
    };

    const getGroupSummary = (groupTools: Tool[]) => {
        const total = groupTools.length;
        const expired = groupTools.filter(t => t.status.text === 'Vencida').length;
        const expiring = groupTools.filter(t => t.status.text === 'Por Vencer').length;

        return { total, expired, expiring };
    };

    return (
        <div className="h-full flex flex-col bg-gray-100 dark:bg-gray-900">
            <header className="sticky top-0 z-10 bg-gray-100 dark:bg-gray-900 flex flex-col md:flex-row justify-between md:items-center gap-4 px-6 md:px-8 py-4 border-b border-gray-200 dark:border-gray-700 shadow-sm">
                <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Gestión de Herramientas</h1>
                <div className="flex items-center gap-4">
                    <div className="relative">
                        <input
                            type="text"
                            value={searchTerm}
                            onChange={e => setSearchTerm(e.target.value)}
                            placeholder="Buscar por serial o nombre..."
                            className="w-full p-2 pl-10 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 text-gray-900 dark:text-white dark:placeholder-gray-400"
                        />
                        <div className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 dark:text-gray-500"><SearchIcon /></div>
                    </div>
                    <button 
                        onClick={() => generatePDFReport(tools)}
                        title="Generar Informe PDF"
                        className="bg-green-600 text-white py-2 px-4 rounded-lg hover:bg-green-700 transition duration-300 flex items-center justify-center gap-2 text-sm font-semibold shadow-md">
                        <PdfIcon /> <span>Generar Informe</span>
                    </button>
                    <button 
                        onClick={() => handleOpenToolForm(null)} 
                        className="bg-blue-600 text-white py-2 px-4 rounded-lg hover:bg-blue-700 transition duration-300 flex items-center justify-center gap-2 text-sm font-semibold shadow-md disabled:bg-gray-400 disabled:cursor-not-allowed"
                        disabled={userRole !== 'Admin'}
                    >
                        <PlusIcon /> <span>Nueva Herramienta</span>
                    </button>
                </div>
            </header>

            <div className="flex-grow overflow-y-auto custom-scrollbar p-6 md:p-8">
                <div className="space-y-4">
                    {Object.keys(groupedTools).length > 0 ? (
                        Object.entries(groupedTools).map(([groupName, groupTools]: [string, Tool[]]) => {
                            const isExpanded = expandedGroups.has(groupName);
                            const summary = getGroupSummary(groupTools);

                            return (
                                <div key={groupName} className="bg-white dark:bg-gray-800 rounded-lg shadow-md overflow-hidden border border-gray-200 dark:border-gray-700">
                                    <button 
                                        onClick={() => toggleGroup(groupName)}
                                        className="w-full flex items-center justify-between p-4 cursor-pointer bg-gray-50 dark:bg-gray-700 hover:bg-gray-100 dark:hover:bg-gray-600 transition-colors select-none text-left focus:outline-none focus:ring-2 focus:ring-inset focus:ring-blue-500"
                                    >
                                        <div className="flex items-center gap-3">
                                            <div className="text-gray-500 dark:text-gray-400">
                                                {isExpanded ? <ChevronDownIcon /> : <ChevronRightIcon />}
                                            </div>
                                            <h3 className="text-lg font-bold text-gray-800 dark:text-white">{groupName}</h3>
                                            <span className="bg-gray-200 dark:bg-gray-600 text-gray-700 dark:text-gray-100 text-xs px-2 py-0.5 rounded-full font-mono font-bold">
                                                {summary.total}
                                            </span>
                                        </div>
                                        <div className="flex gap-2 text-sm">
                                            {summary.expired > 0 && (
                                                <span className="text-red-700 dark:text-red-300 font-bold bg-red-100 dark:bg-red-900/40 px-2 py-0.5 rounded border border-red-200 dark:border-red-800">
                                                    {summary.expired} Vencida{summary.expired > 1 ? 's' : ''}
                                                </span>
                                            )}
                                            {summary.expiring > 0 && (
                                                <span className="text-yellow-700 dark:text-yellow-300 font-bold bg-yellow-100 dark:bg-yellow-900/40 px-2 py-0.5 rounded border border-yellow-200 dark:border-yellow-800">
                                                    {summary.expiring} Por Vencer
                                                </span>
                                            )}
                                            {summary.expired === 0 && summary.expiring === 0 && (
                                                <span className="text-green-600 dark:text-green-400 font-bold flex items-center gap-1">
                                                    <i className="fas fa-check-circle"></i> OK
                                                </span>
                                            )}
                                        </div>
                                    </button>

                                    {isExpanded && (
                                        <div className="overflow-x-auto border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
                                            <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
                                                <thead className="bg-gray-100 dark:bg-gray-900">
                                                    <tr>
                                                        <th scope="col" className="px-6 py-3 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Detalle / Tipo</th>
                                                        <th scope="col" className="px-6 py-3 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Serial</th>
                                                        <th scope="col" className="px-6 py-3 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Última Insp.</th>
                                                        <th scope="col" className="px-6 py-3 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Próxima Insp.</th>
                                                        <th scope="col" className="px-6 py-3 text-center text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Días</th>
                                                        <th scope="col" className="px-6 py-3 text-center text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Estado</th>
                                                        <th scope="col" className="px-6 py-3 text-right text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Acciones</th>
                                                    </tr>
                                                </thead>
                                                <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
                                                    {groupTools.map(tool => (
                                                        <tr key={tool.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                                            <td className="px-6 py-4 whitespace-nowrap">
                                                                <div className="text-sm font-semibold text-gray-900 dark:text-gray-100">{tool.detalle || '-'}</div>
                                                                <div className="text-xs text-gray-500 dark:text-gray-400">{tool.tipo}</div>
                                                            </td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600 dark:text-gray-300 font-mono">{tool.serial}</td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600 dark:text-gray-300">{formatDate(tool.ultimaInspeccion)}</td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600 dark:text-gray-300">
                                                                {tool.nextInspectionDate ? tool.nextInspectionDate.toLocaleDateString('es-ES', { day: '2-digit', month: '2-digit', year: 'numeric'}) : 'N/A'}
                                                            </td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-center text-sm font-bold">
                                                                {tool.status.text === 'Por Vencer' && tool.daysUntilExpiry !== null && tool.daysUntilExpiry !== undefined ? (
                                                                    <span className="text-yellow-600 dark:text-yellow-400">{tool.daysUntilExpiry}</span>
                                                                ) : (
                                                                    <span className="text-gray-400 dark:text-gray-600">-</span>
                                                                )}
                                                            </td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-center">
                                                                <span className={`px-3 py-1 inline-flex text-xs leading-5 font-bold rounded-full border ${getStatusChipClass(tool.status)}`}>
                                                                    {tool.status.text}
                                                                </span>
                                                            </td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                                                                <button onClick={() => handleOpenToolForm(tool)} className="text-indigo-600 hover:text-indigo-900 dark:text-indigo-400 dark:hover:text-indigo-300 mr-4 disabled:opacity-50 disabled:cursor-not-allowed" title="Editar" disabled={userRole !== 'Admin'}><PencilIcon /></button>
                                                                <button onClick={() => handleDeleteTool(tool.id)} className="text-red-600 hover:text-red-900 dark:text-red-400 dark:hover:text-red-300 disabled:opacity-50 disabled:cursor-not-allowed" title="Eliminar" disabled={userRole !== 'Admin'}><TrashIcon /></button>
                                                            </td>
                                                        </tr>
                                                    ))}
                                                </tbody>
                                            </table>
                                        </div>
                                    )}
                                </div>
                            );
                        })
                    ) : (
                        <div className="text-center text-gray-500 dark:text-gray-400 p-8 bg-white dark:bg-gray-800 rounded-lg shadow-md border border-gray-200 dark:border-gray-700">
                            {searchTerm ? 'No se encontraron herramientas que coincidan con la búsqueda.' : 'No hay herramientas cargadas en el sistema.'}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

