export default DiagramaView;

import type { Tool } from '../types';

export type ReportSortOption = 'status' | 'tipo' | 'herramienta';

export const generatePDFReport = (tools: Tool[], sortBy: ReportSortOption = 'status') => {
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF();

    let toolsToReport: Tool[] = [];
    let reportTitle: string = "Informe de Inspecciones";

    switch (sortBy) {
        case 'tipo':
            reportTitle = "Informe de Herramientas por Tipo";
            toolsToReport = [...tools].sort((a, b) => {
                const typeCompare = a.tipo.localeCompare(b.tipo);
                if (typeCompare !== 0) return typeCompare;
                const toolNameCompare = a.herramienta.localeCompare(b.herramienta);
                if (toolNameCompare !== 0) return toolNameCompare;
                return a.serial.localeCompare(b.serial);
            });
            break;

        case 'herramienta':
            reportTitle = "Informe de Herramientas por Nombre";
            toolsToReport = [...tools].sort((a, b) => {
                const toolNameCompare = a.herramienta.localeCompare(b.herramienta);
                if (toolNameCompare !== 0) return toolNameCompare;
                return a.serial.localeCompare(b.serial);
            });
            break;

        case 'status':
        default:
            reportTitle = "Informe de Herramientas Vencidas y Por Vencer";
            toolsToReport = tools.filter(tool => tool.status.text === 'Vencida' || tool.status.text === 'Por Vencer');
            const statusOrder: { [key: string]: number } = { 'Vencida': 1, 'Por Vencer': 2 };
            toolsToReport.sort((a, b) => {
                const orderA = statusOrder[a.status.text] || 3;
                const orderB = statusOrder[b.status.text] || 3;
                if (orderA !== orderB) return orderA - orderB;
                const dateA = a.nextInspectionDate?.getTime() || 0;
                const dateB = b.nextInspectionDate?.getTime() || 0;
                return dateA - dateB;
            });
            break;
    }

    if (toolsToReport.length === 0) {
        alert("No hay herramientas para incluir en este tipo de informe.");
        return;
    }

    const tableColumn = ["Herramienta", "Serial", "Estado", "Fecha de Vencimiento"];
    const tableRows = toolsToReport.map(tool => [
        `${tool.herramienta} ${tool.detalle || ''}`.trim(),
        tool.serial,
        tool.status.text,
        tool.nextInspectionDate ? tool.nextInspectionDate.toLocaleDateString('es-ES') : 'N/A'
    ]);

    const reportDate = new Date().toLocaleDateString('es-ES');

    // Using declare to assert the type of autoTable
    (doc as any).autoTable({ 
        head: [tableColumn], 
        body: tableRows, 
        startY: 35,
        margin: { top: 35 }, // Ensures header margin is applied to all pages
        theme: 'grid', 
        headStyles: { fillColor: [22, 160, 133] },
        didDrawPage: (data: any) => {
            // Header for every page
            doc.setFontSize(11);
            doc.setTextColor(100);
            doc.text(`Fecha: ${reportDate}`, 14, 15);

            doc.setFontSize(18);
            doc.setTextColor(0);
            doc.setFont('helvetica', 'bold');
            doc.text(reportTitle, 14, 25);

            // Optional: Footer with page number
            const str = "Página " + doc.internal.getNumberOfPages();
            doc.setFontSize(10);
            doc.setTextColor(150);
            const pageSize = doc.internal.pageSize;
            const pageHeight = pageSize.height ? pageSize.height : pageSize.getHeight();
            doc.text(str, data.settings.margin.left, pageHeight - 10);
        }
    });

    const safeTitle = reportTitle.replace(/ /g, '_').toLowerCase();
    doc.save(`${safeTitle}_${reportDate.replace(/\//g, '-')}.pdf`);
};

import React, { useState, useMemo, useEffect } from 'react';
import type { Tool, Role } from '../types';
import { generatePDFReport, ReportSortOption } from '../services/reportService';
import { PlusIcon, PencilIcon, TrashIcon, PdfIcon, SearchIcon, ChevronDownIcon, ChevronRightIcon } from '../components/icons';
import Modal from '../components/Modal';

interface ToolManagementViewProps {
    tools: Tool[];
    handleOpenToolForm: (tool: Tool | null) => void;
    handleDeleteTool: (toolId: string) => void;
    userRole: Role | null;
}

const ToolManagementView: React.FC<ToolManagementViewProps> = ({ tools, handleOpenToolForm, handleDeleteTool, userRole }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());
    const [isReportModalOpen, setIsReportModalOpen] = useState(false);

    const filteredTools = useMemo(() => {
        if (!searchTerm) {
            return tools;
        }
        return tools.filter(tool =>
            tool.serial.toLowerCase().includes(searchTerm.toLowerCase()) ||
            tool.herramienta.toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [tools, searchTerm]);

    const groupedTools = useMemo(() => {
        const groups: { [key: string]: Tool[] } = {};
        filteredTools.forEach(tool => {
            const key = tool.herramienta;
            if (!groups[key]) {
                groups[key] = [];
            }
            groups[key].push(tool);
        });

        return Object.keys(groups).sort().reduce((obj, key) => {
            obj[key] = groups[key];
            return obj;
        }, {} as { [key: string]: Tool[] });
    }, [filteredTools]);

    useEffect(() => {
        if (searchTerm) {
            setExpandedGroups(new Set(Object.keys(groupedTools)));
        }
    }, [searchTerm, groupedTools]);

    const toggleGroup = (groupName: string) => {
        setExpandedGroups(prev => {
            const next = new Set(prev);
            if (next.has(groupName)) {
                next.delete(groupName);
            } else {
                next.add(groupName);
            }
            return next;
        });
