                        disabled={userRole !== 'Admin'}
                    >
                        <PlusIcon /> <span>Nueva Herramienta</span>
                    </button>
                </div>
            </header>

            <div className="flex-grow overflow-y-auto custom-scrollbar p-6 md:p-8">
                <div className="space-y-4">
                    {Object.keys(groupedTools).length > 0 ? (
                        Object.entries(groupedTools).map(([groupName, groupTools]: [string, Tool[]]) => {
                            const isExpanded = expandedGroups.has(groupName);
                            const summary = getGroupSummary(groupTools);

                            return (
                                <div key={groupName} className="bg-white dark:bg-gray-800 rounded-lg shadow-md overflow-hidden border border-gray-200 dark:border-gray-700">
                                    <button 
                                        onClick={() => toggleGroup(groupName)}
                                        className="w-full flex items-center justify-between p-4 cursor-pointer bg-gray-50 dark:bg-gray-700 hover:bg-gray-100 dark:hover:bg-gray-600 transition-colors select-none text-left focus:outline-none focus:ring-2 focus:ring-inset focus:ring-blue-500"
                                    >
                                        <div className="flex items-center gap-3">
                                            <div className="text-gray-500 dark:text-gray-400">
                                                {isExpanded ? <ChevronDownIcon /> : <ChevronRightIcon />}
                                            </div>
                                            <h3 className="text-lg font-bold text-gray-800 dark:text-white">{groupName}</h3>
                                            <span className="bg-gray-200 dark:bg-gray-600 text-gray-700 dark:text-gray-100 text-xs px-2 py-0.5 rounded-full font-mono font-bold">
                                                {summary.total}
                                            </span>
                                        </div>
                                        <div className="flex gap-2 text-sm">
                                            {summary.expired > 0 && (
                                                <span className="text-red-700 dark:text-red-300 font-bold bg-red-100 dark:bg-red-900/40 px-2 py-0.5 rounded border border-red-200 dark:border-red-800">
                                                    {summary.expired} Vencida{summary.expired > 1 ? 's' : ''}
                                                </span>
                                            )}
                                            {summary.expiring > 0 && (
                                                <span className="text-yellow-700 dark:text-yellow-300 font-bold bg-yellow-100 dark:bg-yellow-900/40 px-2 py-0.5 rounded border border-yellow-200 dark:border-yellow-800">
                                                    {summary.expiring} Por Vencer
                                                </span>
                                            )}
                                            {summary.expired === 0 && summary.expiring === 0 && (
                                                <span className="text-green-600 dark:text-green-400 font-bold flex items-center gap-1">
                                                    <i className="fas fa-check-circle"></i> OK
                                                </span>
                                            )}
                                        </div>
                                    </button>

                                    {isExpanded && (
                                        <div className="overflow-x-auto border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
                                            <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
                                                <thead className="bg-gray-100 dark:bg-gray-900">
                                                    <tr>
                                                        <th scope="col" className="px-6 py-3 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Detalle / Tipo</th>
                                                        <th scope="col" className="px-6 py-3 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Serial</th>
                                                        <th scope="col" className="px-6 py-3 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Última Insp.</th>
                                                        <th scope="col" className="px-6 py-3 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Próxima Insp.</th>
                                                        <th scope="col" className="px-6 py-3 text-center text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Días</th>
                                                        <th scope="col" className="px-6 py-3 text-center text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Estado</th>
                                                        <th scope="col" className="px-6 py-3 text-right text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Acciones</th>
                                                    </tr>
                                                </thead>
                                                <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
                                                    {groupTools.map(tool => (
                                                        <tr key={tool.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                                            <td className="px-6 py-4 whitespace-nowrap">
                                                                <div className="text-sm font-semibold text-gray-900 dark:text-gray-100">{tool.detalle || '-'}</div>
                                                                <div className="text-xs text-gray-500 dark:text-gray-400">{tool.tipo}</div>
