            doc.setFontSize(11);
            doc.setTextColor(100);
            doc.text(`Fecha: ${reportDate}`, 14, 15);

            doc.setFontSize(18);
            doc.setTextColor(0);
            doc.setFont('helvetica', 'bold');
            doc.text(reportTitle, 14, 25);

            // Optional: Footer with page number
            const str = "Página " + doc.internal.getNumberOfPages();
            doc.setFontSize(10);
            doc.setTextColor(150);
            const pageSize = doc.internal.pageSize;
            const pageHeight = pageSize.height ? pageSize.height : pageSize.getHeight();
            doc.text(str, data.settings.margin.left, pageHeight - 10);
        }
    });

    const safeTitle = reportTitle.replace(/ /g, '_').toLowerCase();
    doc.save(`${safeTitle}_${reportDate.replace(/\//g, '-')}.pdf`);
};

import React, { useState, useMemo, useEffect } from 'react';
import type { Tool, Role } from '../types';
import { generatePDFReport, ReportSortOption } from '../services/reportService';
import { PlusIcon, PencilIcon, TrashIcon, PdfIcon, SearchIcon, ChevronDownIcon, ChevronRightIcon } from '../components/icons';
import Modal from '../components/Modal';

interface ToolManagementViewProps {
    tools: Tool[];
    handleOpenToolForm: (tool: Tool | null) => void;
    handleDeleteTool: (toolId: string) => void;
    userRole: Role | null;
}

const ToolManagementView: React.FC<ToolManagementViewProps> = ({ tools, handleOpenToolForm, handleDeleteTool, userRole }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());
    const [isReportModalOpen, setIsReportModalOpen] = useState(false);

    const filteredTools = useMemo(() => {
        if (!searchTerm) {
            return tools;
        }
        return tools.filter(tool =>
            tool.serial.toLowerCase().includes(searchTerm.toLowerCase()) ||
            tool.herramienta.toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [tools, searchTerm]);

    const groupedTools = useMemo(() => {
        const groups: { [key: string]: Tool[] } = {};
        filteredTools.forEach(tool => {
            const key = tool.herramienta;
            if (!groups[key]) {
                groups[key] = [];
            }
            groups[key].push(tool);
        });

        return Object.keys(groups).sort().reduce((obj, key) => {
            obj[key] = groups[key];
            return obj;
        }, {} as { [key: string]: Tool[] });
    }, [filteredTools]);

    useEffect(() => {
        if (searchTerm) {
            setExpandedGroups(new Set(Object.keys(groupedTools)));
        }
    }, [searchTerm, groupedTools]);

    const toggleGroup = (groupName: string) => {
        setExpandedGroups(prev => {
            const next = new Set(prev);
            if (next.has(groupName)) {
                next.delete(groupName);
            } else {
                next.add(groupName);
            }
            return next;
        });
    };

    const handleGenerateReport = (sortBy: ReportSortOption) => {
        generatePDFReport(tools, sortBy);
        setIsReportModalOpen(false);
    };

    const getStatusChipClass = (status: Tool['status']) => {
        switch(status.color) {
            case 'green': return 'bg-green-100 text-green-800 dark:bg-green-900/40 dark:text-green-300';
            case 'yellow': return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/40 dark:text-yellow-300';
            case 'red': return 'bg-red-100 text-red-800 dark:bg-red-900/40 dark:text-red-300';
            default: return 'bg-gray-100 text-gray-800 dark:bg-gray-600 dark:text-gray-200';
        }
    };

    const formatDate = (dateString: string) => {
        if (!dateString) return 'N/A';
        try {
            const [year, month, day] = dateString.split('-');
            if (!year || !month || !day) return dateString;
            return `${day}/${month}/${year}`;
        } catch (e) {
            return dateString;
        }
    };

    const getGroupSummary = (groupTools: Tool[]) => {
        const total = groupTools.length;
        const expired = groupTools.filter(t => t.status.text === 'Vencida').length;
        const expiring = groupTools.filter(t => t.status.text === 'Por Vencer').length;

        return { total, expired, expiring };
    };

    return (
        <div className="h-full flex flex-col bg-gray-100 dark:bg-gray-900">
            <header className="sticky top-0 z-10 bg-gray-100 dark:bg-gray-900 flex flex-col md:flex-row justify-between md:items-center gap-4 px-6 md:px-8 py-4 border-b border-gray-200 dark:border-gray-700 shadow-sm">
                <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Gestión de Herramientas</h1>
                <div className="flex items-center gap-4">
                    <div className="relative">
                        <input
                            type="text"
                            value={searchTerm}
                            onChange={e => setSearchTerm(e.target.value)}
                            placeholder="Buscar por serial o nombre..."
                            className="w-full p-2 pl-10 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 text-gray-900 dark:text-white dark:placeholder-gray-400"
                        />
                        <div className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 dark:text-gray-500"><SearchIcon /></div>
                    </div>
                    <button 
                        onClick={() => setIsReportModalOpen(true)}
                        title="Generar Informe PDF"
                        className="bg-green-600 text-white py-2 px-4 rounded-lg hover:bg-green-700 transition duration-300 flex items-center justify-center gap-2 text-sm font-semibold shadow-md">
                        <PdfIcon /> <span>Generar Informe</span>
                    </button>
                    <button 
                        onClick={() => handleOpenToolForm(null)} 
                        className="bg-blue-600 text-white py-2 px-4 rounded-lg hover:bg-blue-700 transition duration-300 flex items-center justify-center gap-2 text-sm font-semibold shadow-md disabled:bg-gray-400 disabled:cursor-not-allowed"
                        disabled={userRole !== 'Admin'}
                    >
                        <PlusIcon /> <span>Nueva Herramienta</span>
                    </button>
                </div>
            </header>

            <div className="flex-grow overflow-y-auto custom-scrollbar p-6 md:p-8">
                <div className="space-y-4">
                    {Object.keys(groupedTools).length > 0 ? (
                        Object.entries(groupedTools).map(([groupName, groupTools]: [string, Tool[]]) => {
                            const isExpanded = expandedGroups.has(groupName);
                            const summary = getGroupSummary(groupTools);

                            return (
                                <div key={groupName} className="bg-white dark:bg-gray-800 rounded-lg shadow-md overflow-hidden border border-gray-200 dark:border-gray-700">
                                    <button 
                                        onClick={() => toggleGroup(groupName)}
                                        className="w-full flex items-center justify-between p-4 cursor-pointer bg-gray-50 dark:bg-gray-700 hover:bg-gray-100 dark:hover:bg-gray-600 transition-colors select-none text-left focus:outline-none focus:ring-2 focus:ring-inset focus:ring-blue-500"
                                    >
                                        <div className="flex items-center gap-3">
                                            <div className="text-gray-500 dark:text-gray-400">
                                                {isExpanded ? <ChevronDownIcon /> : <ChevronRightIcon />}
                                            </div>
                                            <h3 className="text-lg font-bold text-gray-800 dark:text-white">{groupName}</h3>
                                            <span className="bg-gray-200 dark:bg-gray-600 text-gray-700 dark:text-gray-100 text-xs px-2 py-0.5 rounded-full font-mono font-bold">
                                                {summary.total}
                                            </span>
                                        </div>
                                        <div className="flex gap-2 text-sm">
                                            {summary.expired > 0 && (
                                                <span className="text-red-700 dark:text-red-300 font-bold bg-red-100 dark:bg-red-900/40 px-2 py-0.5 rounded border border-red-200 dark:border-red-800">
                                                    {summary.expired} Vencida{summary.expired > 1 ? 's' : ''}
                                                </span>
                                            )}
                                            {summary.expiring > 0 && (
                                                <span className="text-yellow-700 dark:text-yellow-300 font-bold bg-yellow-100 dark:bg-yellow-900/40 px-2 py-0.5 rounded border border-yellow-200 dark:border-yellow-800">
                                                    {summary.expiring} Por Vencer
                                                </span>
                                            )}
                                            {summary.expired === 0 && summary.expiring === 0 && (
                                                <span className="text-green-600 dark:text-green-400 font-bold flex items-center gap-1">
                                                    <i className="fas fa-check-circle"></i> OK
                                                </span>
                                            )}
                                        </div>
                                    </button>

                                    {isExpanded && (
                                        <div className="overflow-x-auto border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
                                            <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
                                                <thead className="bg-gray-100 dark:bg-gray-900">
                                                    <tr>
                                                        <th scope="col" className="px-6 py-3 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Detalle / Tipo</th>
                                                        <th scope="col" className="px-6 py-3 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Serial</th>
                                                        <th scope="col" className="px-6 py-3 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Última Insp.</th>
                                                        <th scope="col" className="px-6 py-3 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Próxima Insp.</th>
                                                        <th scope="col" className="px-6 py-3 text-center text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Días</th>
                                                        <th scope="col" className="px-6 py-3 text-center text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Estado</th>
                                                        <th scope="col" className="px-6 py-3 text-right text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Acciones</th>
                                                    </tr>
                                                </thead>
                                                <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
                                                    {groupTools.map(tool => (
                                                        <tr key={tool.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                                            <td className="px-6 py-4 whitespace-nowrap">
                                                                <div className="text-sm font-semibold text-gray-900 dark:text-gray-100">{tool.detalle || '-'}</div>
                                                                <div className="text-xs text-gray-500 dark:text-gray-400">{tool.tipo}</div>
                                                            </td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600 dark:text-gray-300 font-mono">{tool.serial}</td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600 dark:text-gray-300">{formatDate(tool.ultimaInspeccion)}</td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600 dark:text-gray-300">
                                                                {tool.nextInspectionDate ? tool.nextInspectionDate.toLocaleDateString('es-ES', { day: '2-digit', month: '2-digit', year: 'numeric'}) : 'N/A'}
                                                            </td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-center text-sm font-bold">
                                                                {tool.status.text === 'Por Vencer' && tool.daysUntilExpiry !== null && tool.daysUntilExpiry !== undefined ? (
                                                                    <span className="text-yellow-600 dark:text-yellow-400">{tool.daysUntilExpiry}</span>
                                                                ) : (
                                                                    <span className="text-gray-400 dark:text-gray-600">-</span>
                                                                )}
                                                            </td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-center">
                                                                <span className={`px-3 py-1 inline-flex text-xs leading-5 font-bold rounded-full border ${getStatusChipClass(tool.status)}`}>
                                                                    {tool.status.text}
                                                                </span>
                                                            </td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                                                                <button onClick={() => handleOpenToolForm(tool)} className="text-indigo-600 hover:text-indigo-900 dark:text-indigo-400 dark:hover:text-indigo-300 mr-4 disabled:opacity-50 disabled:cursor-not-allowed" title="Editar" disabled={userRole !== 'Admin'}><PencilIcon /></button>
                                                                <button onClick={() => handleDeleteTool(tool.id)} className="text-red-600 hover:text-red-900 dark:text-red-400 dark:hover:text-red-300 disabled:opacity-50 disabled:cursor-not-allowed" title="Eliminar" disabled={userRole !== 'Admin'}><TrashIcon /></button>
                                                            </td>
                                                        </tr>
                                                    ))}
                                                </tbody>
                                            </table>
                                        </div>
                                    )}
                                </div>
                            );
                        })
                    ) : (
                        <div className="text-center text-gray-500 dark:text-gray-400 p-8 bg-white dark:bg-gray-800 rounded-lg shadow-md border border-gray-200 dark:border-gray-700">
                            {searchTerm ? 'No se encontraron herramientas que coincidan con la búsqueda.' : 'No hay herramientas cargadas en el sistema.'}
                        </div>
                    )}
                </div>
            </div>

            <Modal isOpen={isReportModalOpen} onClose={() => setIsReportModalOpen(false)}>
                <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-md w-full max-w-md">
                    <h2 className="text-xl font-bold mb-6 text-gray-800 dark:text-gray-100">Opciones de Informe PDF</h2>
                    <div className="space-y-3">
                        <button
                            onClick={() => handleGenerateReport('status')}
                            className="w-full text-left p-4 bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 rounded-lg transition border border-gray-200 dark:border-gray-600"
                        >
                            <p className="font-semibold text-gray-800 dark:text-gray-100">Por Estado (Prioridad)</p>
                            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">Informe acotado. Incluye solo herramientas vencidas y por vencer, ordenadas por urgencia.</p>
                        </button>
                        <button
                            onClick={() => handleGenerateReport('tipo')}
                            className="w-full text-left p-4 bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 rounded-lg transition border border-gray-200 dark:border-gray-600"
                        >
                            <p className="font-semibold text-gray-800 dark:text-gray-100">Por Tipo de Herramienta</p>
                            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">Informe acotado. Incluye solo herramientas vencidas y por vencer, agrupadas por tipo.</p>
                        </button>
                        <button
                            onClick={() => handleGenerateReport('herramienta')}
                            className="w-full text-left p-4 bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 rounded-lg transition border border-gray-200 dark:border-gray-600"
                        >
                            <p className="font-semibold text-gray-800 dark:text-gray-100">Por Nombre de Herramienta</p>
                            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">Informe acotado. Incluye solo herramientas vencidas y por vencer, ordenadas alfabéticamente por nombre.</p>
                        </button>
                    </div>
                    <div className="mt-8 flex justify-end">
                        <button onClick={() => setIsReportModalOpen(false)} className="bg-gray-500 text-white py-2 px-6 rounded-lg hover:bg-gray-600 transition">Cancelar</button>
                    </div>
                </div>
            </Modal>
        </div>
    );
};

export default ToolManagementView;

import React, { useState, useEffect, useMemo, useCallback } from 'react';

// Types
import type { Tool, Operation, Personnel, Course, User, Role, Vehicle } from './types';

// Services
import {
    initializeAirtable, testAirtableConnection,
    getTools, createTool, updateTool, deleteTool,
    getOperations, createOperation, updateOperation, deleteOperation,
    getPersonnel, createPersonnel, updatePersonnel, deletePersonnel,
    getCourses, createCourse, updateCourse, deleteCourse,
    getUsers, createUser, updateUser, deleteUser,
    getVehicles, createVehicle, updateVehicle, deleteVehicle
} from './services/airtableApiService';
import { generateRMReport } from './services/reportService';


// Views
import CanvasView from './views/CanvasView';
import ToolManagementView from './views/ToolManagementView';
import OperationsView from './views/OperationsView';
import MaintenanceView from './views/MaintenanceView';
import PersonnelView from './views/PersonnelView';
import CoursesView from './views/CoursesView';
import DiagramaView from './views/DiagramaView';
import SettingsView from './views/SettingsView';
import VehiclesView from './views/VehiclesView';

// Components
import LoginScreen from './components/LoginScreen';
import ToolFormModal from './components/ToolFormModal';
import OperationFormModal from './components/OperationFormModal';
import NotificationFormModal from './components/NotificationFormModal';
import ConfirmModal from './components/ConfirmModal';
import AlertModal from './components/AlertModal';
import CourseFormModal from './components/CourseFormModal';
import PersonnelFormModal from './components/PersonnelFormModal';
import UserFormModal from './components/UserFormModal';
import VehicleFormModal from './components/VehicleFormModal';
import RMReportModal from './components/RMReportModal';
import {
    GridViewIcon, WrenchIcon, ClipboardListIcon, ShieldCheckIcon,
    UsersIcon, BookOpenIcon, CalendarDaysIcon, SettingsIcon,
    LogoutIcon, MoonIcon, SunIcon, TruckIcon, SyncIcon
} from './components/icons';

// Main view types
export type View = 'Canvas' | 'Tools' | 'Operations' | 'Maintenance' | 'Personnel' | 'Courses' | 'Diagrama' | 'Vehicles' | 'Settings';

const App: React.FC = () => {
    // Loading and error state
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    // Data state
    const [tools, setTools] = useState<Tool[]>([]);
    const [operations, setOperations] = useState<Operation[]>([]);
    const [personnel, setPersonnel] = useState<Personnel[]>([]);
    const [courses, setCourses] = useState<Course[]>([]);
    const [users, setUsers] = useState<User[]>([]);
    const [vehicles, setVehicles] = useState<Vehicle[]>([]);

    // UI and Auth state
    const [currentUser, setCurrentUser] = useState<{ username: string; role: Role } | null>(null);
    const [currentView, setCurrentView] = useState<View>('Canvas');
    const [isDarkMode, setIsDarkMode] = useState(false);
    const [isPresentationModeActive, setPresentationModeActive] = useState(false);


    // Modal states
    const [isToolFormOpen, setIsToolFormOpen] = useState(false);
    const [editingTool, setEditingTool] = useState<Tool | null>(null);

    const [isOperationFormOpen, setIsOperationFormOpen] = useState(false);
    const [editingOperation, setEditingOperation] = useState<Operation | null>(null);

    const [isNotificationFormOpen, setIsNotificationFormOpen] = useState(false);
    const [notificationTool, setNotificationTool] = useState<Tool | null>(null);

    const [isCourseFormOpen, setIsCourseFormOpen] = useState(false);
    const [editingCourse, setEditingCourse] = useState<Course | null>(null);

    const [isPersonnelFormOpen, setIsPersonnelFormOpen] = useState(false);
    const [editingPersonnel, setEditingPersonnel] = useState<Personnel | null>(null);

    const [isUserFormOpen, setIsUserFormOpen] = useState(false);
    const [editingUser, setEditingUser] = useState<User | null>(null);

    const [isVehicleFormOpen, setIsVehicleFormOpen] = useState(false);
    const [editingVehicle, setEditingVehicle] = useState<Vehicle | null>(null);

    const [isRMReportModalOpen, setIsRMReportModalOpen] = useState(false);

    const [confirmModal, setConfirmModal] = useState({ isOpen: false, title: '', text: '', onConfirm: () => {} });
    const [alertModal, setAlertModal] = useState({ isOpen: false, title: '', text: '' });

    // Data fetching logic
    const handleRefreshData = useCallback(async () => {
        if (!currentUser) return;
        setIsLoading(true);
        setError(null);
        try {
            const [toolsData, operationsData, personnelData, coursesData, vehiclesData] = await Promise.all([
                getTools(),
                getOperations(),
                getPersonnel(),
                getCourses(),
                getVehicles(),
            ]);
            setTools(toolsData);
            setOperations(operationsData);
            setPersonnel(personnelData);
            setCourses(coursesData);
            setVehicles(vehiclesData);
        } catch (err: any) {
            setError(err.message || 'Error al cargar los datos de la aplicación.');
            showAlert('Error de Actualización', err.message || 'No se pudieron cargar los datos más recientes.');
        } finally {
            setIsLoading(false);
        }
    }, [currentUser]);

    // Initial load: Fetch only users first
    const fetchInitialData = useCallback(async () => {
        setIsLoading(true);
        setError(null);
        try {
            initializeAirtable();
            await testAirtableConnection();
            const usersData = await getUsers();
            setUsers(usersData);
        } catch (err: any) {
            setError(err.message || 'Error al cargar los datos de configuración.');
        } finally {
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchInitialData();
         // Dark mode setup
        const darkModePreference = localStorage.getItem('darkMode') === 'true';
        setIsDarkMode(darkModePreference);
        document.documentElement.classList.toggle('dark', darkModePreference);
    }, [fetchInitialData]);

    // Fetch all other data after successful login
    useEffect(() => {
        if (currentUser) {
            handleRefreshData();
        }
    }, [currentUser, handleRefreshData]);


    const toggleDarkMode = () => {
        setIsDarkMode(prev => {
            const newMode = !prev;
            localStorage.setItem('darkMode', String(newMode));
            document.documentElement.classList.toggle('dark', newMode);
            return newMode;
        });
    };

    // Derived state
    const assignedToolIds = useMemo(() => {
        const ids = new Set<string>();
        operations.forEach(op => {
            if (op.assignedTools) {
                op.assignedTools.forEach(toolId => ids.add(toolId));
            }
        });
        return ids;
    }, [operations]);

    // Handlers
    const handleLoginSuccess = (user: { username: string; role: Role }) => {
        setCurrentUser(user);
    };

    const handleLogout = () => {
        setCurrentUser(null);
        setCurrentView('Canvas');
    };

    const showAlert = (title: string, text: string) => {
        setAlertModal({ isOpen: true, title, text });
    };

    // --- CRUD Handlers ---
    const handleSaveTool = async (tool: Omit<Tool, 'id' | 'nextInspectionDate' | 'status'> & { id?: string }) => {
        try {
            if (tool.id) {
                await updateTool(tool.id, tool);
            } else {
                await createTool(tool);
            }
            setTools(await getTools());
            setIsToolFormOpen(false);
        } catch (err: any) {
            showAlert('Error', err.message || 'No se pudo guardar la herramienta.');
        }
    };

    const handleDeleteTool = (toolId: string) => {
        setConfirmModal({
            isOpen: true,
            title: 'Confirmar Eliminación',
            text: '¿Estás seguro de que quieres eliminar esta herramienta? Esta acción no se puede deshacer.',
            onConfirm: async () => {
                try {
                    await deleteTool(toolId);
                    setTools(await getTools());
                } catch (err: any) {
                     showAlert('Error', err.message || 'No se pudo eliminar la herramienta.');
                } finally {
                    setConfirmModal({ isOpen: false, title: '', text: '', onConfirm: () => {} });
                }
            }
        });
    };

    const handleSaveOperation = async (operation: Partial<Operation> & { id?: string }) => {
        try {
            if (operation.id) {
                await updateOperation(operation.id, operation);
            } else {
                await createOperation(operation);
            }
            setOperations(await getOperations());
            setIsOperationFormOpen(false);
        } catch (err: any) {
            showAlert('Error', err.message || 'No se pudo guardar la operación.');
        }
    };

    const handleDeleteOperation = (operationId: string) => {
        setConfirmModal({
            isOpen: true,
            title: 'Confirmar Eliminación',
            text: '¿Estás seguro de que quieres eliminar esta operación?',
            onConfirm: async () => {
                try {
                    await deleteOperation(operationId);
                    setOperations(await getOperations());
                } catch (err: any) {
                    showAlert('Error', err.message || 'No se pudo eliminar la operación.');
                } finally {
                    setConfirmModal({ isOpen: false, title: '', text: '', onConfirm: () => {} });
                }
            }
        });
    };

    const handleSavePersonnel = async (person: Personnel) => {
        try {
            if (person.id) {
                await updatePersonnel(person.id, person);
            } else {
                await createPersonnel(person);
            }
            setPersonnel(await getPersonnel());
            setIsPersonnelFormOpen(false);
        } catch (err: any) {
            showAlert('Error', err.message || 'No se pudo guardar el registro de personal.');
        }
    };

    const handleDeletePersonnel = (personnelId: string) => {
        setConfirmModal({
            isOpen: true,
            title: 'Confirmar Eliminación',
            text: '¿Estás seguro de que quieres eliminar a esta persona?',
            onConfirm: async () => {
                try {
                    await deletePersonnel(personnelId);
                    setPersonnel(await getPersonnel());
                    setConfirmModal({ isOpen: false, title: '', text: '', onConfirm: () => {} });
                } catch (err: any) {
                    showAlert('Error', err.message || 'No se pudo eliminar al personal.');
                }
            }
        });
    };

    const handleSaveCourse = async (course: Course) => {
        try {
            if (course.id) {
                await updateCourse(course.id, course);
            } else {
                await createCourse(course);
            }
            setCourses(await getCourses());
            setIsCourseFormOpen(false);
        } catch (err: any) {
            showAlert('Error', err.message || 'No se pudo guardar el curso.');
        }
    };

    const handleDeleteCourse = (courseId: string) => {
         setConfirmModal({
            isOpen: true,
            title: 'Confirmar Eliminación',
            text: '¿Estás seguro de que quieres eliminar este curso?',
            onConfirm: async () => {
                try {
                    await deleteCourse(courseId);
                    setCourses(await getCourses());
                } catch (err: any) {
                    showAlert('Error', err.message || 'No se pudo eliminar el curso.');
                } finally {
                    setConfirmModal({ isOpen: false, title: '', text: '', onConfirm: () => {} });
                }
            }
        });
    };

    const handleSaveUser = async (user: User) => {
        try {
            if (user.id) {
                await updateUser(user.id, user);
            } else {
                await createUser(user);
            }
            setUsers(await getUsers());
            setIsUserFormOpen(false);
        } catch (err: any) {
            showAlert('Error', err.message || 'No se pudo guardar el usuario.');
        }
    };

    const handleDeleteUser = (userId: string) => {
        if (users.find(u => u.id === userId)?.role === 'Admin') {
            showAlert('Acción no permitida', 'No se puede eliminar al usuario Administrador.');
            return;
        }
        setConfirmModal({
            isOpen: true,
            title: 'Confirmar Eliminación',
            text: '¿Estás seguro de que quieres eliminar este usuario?',
            onConfirm: async () => {
                try {
                    await deleteUser(userId);
                    setUsers(await getUsers());
                } catch (err: any) {
                    showAlert('Error', err.message || 'No se pudo eliminar el usuario.');
                } finally {
                    setConfirmModal({ isOpen: false, title: '', text: '', onConfirm: () => {} });
                }
            }
        });
    };

    const handleSaveVehicle = async (vehicle: Partial<Vehicle>) => {
        try {
            if (vehicle.id) {
                await updateVehicle(vehicle.id, vehicle);
            } else {
                await createVehicle(vehicle);
            }
            setVehicles(await getVehicles());
            setIsVehicleFormOpen(false);
        } catch (err: any) {
            showAlert('Error', err.message || 'No se pudo guardar el vehículo.');
        }
    };

    const handleDeleteVehicle = (vehicleId: string) => {
        setConfirmModal({
            isOpen: true,
            title: 'Confirmar Eliminación',
            text: '¿Estás seguro de que quieres eliminar este vehículo?',
            onConfirm: async () => {
                try {
                    await deleteVehicle(vehicleId);
                    setVehicles(await getVehicles());
                } catch (err: any) {
                    showAlert('Error', err.message || 'No se pudo eliminar el vehículo.');
                } finally {
                    setConfirmModal({ isOpen: false, title: '', text: '', onConfirm: () => {} });
                }
            }
        });
    };

    const handleGenerateRMReport = async (formData: any) => {
        try {
            setIsRMReportModalOpen(false); // Close modal immediately
            showAlert('Generando Informe', 'El informe PDF se está creando. Por favor, espera...');
            // Create a map for easy tool lookup
            const toolsById = tools.reduce((acc, tool) => {
                acc[tool.id] = tool;
                return acc;
            }, {} as { [id: string]: Tool });
            await generateRMReport(formData, operations, toolsById);
            // Close the "generating" alert if it's still open
            setAlertModal(prev => ({ ...prev, isOpen: false }));
        } catch (err: any) {
            showAlert('Error al generar PDF', err.message || 'No se pudo crear el informe.');
        }
    };


    // --- Modal Openers ---
    const handleOpenToolForm = (tool: Tool | null) => {
        setEditingTool(tool);
        setIsToolFormOpen(true);
    };

    const handleOpenOperationForm = (operation: Operation | null) => {
        setEditingOperation(operation);
        setIsOperationFormOpen(true);
    };

    const handleOpenNotificationModal = (toolId: string) => {
        const toolToNotify = tools.find(t => t.id === toolId);
        if (toolToNotify) {
            setNotificationTool(toolToNotify);
            setIsNotificationFormOpen(true);
        }
    };

    const handleOpenCourseForm = (course: Course | null) => {
        setEditingCourse(course);
        setIsCourseFormOpen(true);
    };

    const handleOpenPersonnelForm = (person: Personnel | null) => {
        setEditingPersonnel(person);
        setIsPersonnelFormOpen(true);
    };

    const handleOpenUserForm = (user: User | null) => {
        setEditingUser(user);
        setIsUserFormOpen(true);
    };

    const handleOpenVehicleForm = (vehicle: Vehicle | null) => {
        setEditingVehicle(vehicle);
        setIsVehicleFormOpen(true);
    };

    const handleSaveNotification = async (toolId: string, days: number, emails: string[]) => {
         try {
            await updateTool(toolId, { notificationDays: days, notificationEmails: emails });
            setTools(await getTools());
            setIsNotificationFormOpen(false);
        } catch (err: any) {
             showAlert('Error', err.message || 'No se pudo guardar la notificación.');
        }
    };

    // Drag & Drop
    const handleDropToolOnOperation = async (operationId: string, toolId: string) => {
        const operation = operations.find(op => op.id === operationId);
        if (operation && !operation.assignedTools.includes(toolId)) {
            const updatedTools = [...operation.assignedTools, toolId];
            try {
                await updateOperation(operationId, { assignedTools: updatedTools });
                setOperations(await getOperations());
            } catch (err: any) {
                showAlert('Error', err.message || 'No se pudo asignar la herramienta.');
            }
        }
    };

    const handleRemoveToolFromOperation = async (operationId: string, toolId: string) => {
        const operation = operations.find(op => op.id === operationId);
        if (operation) {
            const updatedTools = operation.assignedTools.filter(id => id !== toolId);
             try {
                await updateOperation(operationId, { assignedTools: updatedTools });
                setOperations(await getOperations());
            } catch (err: any) {
                showAlert('Error', err.message || 'No se pudo liberar la herramienta.');
            }
        }
    };

    // Navigation and View data
    const navItems: { view: View; icon: React.ReactNode; label: string }[] = [
        { view: 'Canvas', icon: <GridViewIcon />, label: 'Canvas' },
        { view: 'Tools', icon: <WrenchIcon />, label: 'Herramientas' },
        { view: 'Operations', icon: <ClipboardListIcon />, label: 'Operaciones' },
        { view: 'Maintenance', icon: <ShieldCheckIcon />, label: 'Mantenimiento' },
        { view: 'Personnel', icon: <UsersIcon />, label: 'Personal' },
        { view: 'Courses', icon: <BookOpenIcon />, label: 'Cursos' },
        { view: 'Diagrama', icon: <CalendarDaysIcon />, label: 'Diagrama' },
        { view: 'Vehicles', icon: <TruckIcon />, label: 'Vehículos' },
        { view: 'Settings', icon: <SettingsIcon />, label: 'Configuración' },
    ];

    const presentationEligibleViews = navItems
        .filter(item => item.view !== 'Settings')
        .map(item => ({ view: item.view, label: item.label }));

    const currentViewLabel = navItems.find(item => item.view === currentView)?.label || 'Tablero';

    // Presentation Mode Logic
    useEffect(() => {
        let intervalId: number | undefined;

        if (isPresentationModeActive) {
            const intervalSeconds = parseInt(localStorage.getItem('presentationInterval') || '120', 10);

            const savedViewsJSON = localStorage.getItem('presentationViews');
            const defaultCycle: View[] = presentationEligibleViews.map(v => v.view);
            let viewCycle: View[] = defaultCycle;

            if (savedViewsJSON) {
                try {
                    const parsedViews = JSON.parse(savedViewsJSON);
                    if (Array.isArray(parsedViews) && parsedViews.length > 0) {
                        viewCycle = parsedViews;
                    }
                } catch (e) {
                    console.error("Could not parse presentation views from localStorage", e);
                }
            }

            if (viewCycle.length > 0) {
                intervalId = window.setInterval(() => {
                    setCurrentView(prevView => {
                        const currentIndex = viewCycle.indexOf(prevView);
                        const nextIndex = (currentIndex === -1) ? 0 : (currentIndex + 1) % viewCycle.length;
                        return viewCycle[nextIndex];
                    });
                }, intervalSeconds * 1000);
            } else {
                setPresentationModeActive(false);
            }
        }

        return () => {
            if (intervalId) {
                clearInterval(intervalId);
            }
        };
    }, [isPresentationModeActive, presentationEligibleViews]);

    const togglePresentationMode = () => {
        setPresentationModeActive(prev => !prev);
    };


    // --- Render Logic ---
    if (isLoading && !currentUser) { // Initial loading for login
        return (
            <div className="flex items-center justify-center h-screen bg-gray-100 dark:bg-gray-900">
                <div className="text-xl font-semibold">Cargando...</div>
            </div>
        );
    }

    if (error && !currentUser) { // Initial error before login
         return (
            <div className="flex items-center justify-center h-screen bg-gray-100 dark:bg-gray-900">
                <div className="bg-white dark:bg-gray-800 p-8 rounded-xl shadow-md w-full max-w-lg text-center">
                    <h2 className="text-2xl font-bold text-red-600 dark:text-red-400 mb-4">Error de Configuración o Conexión</h2>
                    <p className="text-gray-600 dark:text-gray-300 mb-6">{error || 'La librería de Airtable no se ha cargado correctamente.'}</p>
                    <div className="bg-gray-100 dark:bg-gray-700 p-4 rounded-lg text-left text-sm text-gray-500 dark:text-gray-400">
                        <h3 className="font-semibold mb-2">Pasos para solucionar el problema:</h3>
                        <ol className="list-decimal list-inside space-y-1">
                            <li>Asegúrate de tener conexión a internet.</li>
                            <li>Verifica que los valores de 'AIRTABLE_API_KEY' y 'AIRTABLE_BASE_ID' en el archivo `config.ts` son correctos.</li>
                            <li>Revisa la consola del navegador (F12) para ver mensajes de error detallados.</li>
                        </ol>
                    </div>
                    <button onClick={fetchInitialData} className="mt-6 bg-blue-600 text-white py-2 px-6 rounded-lg hover:bg-blue-700 transition">
                        Reintentar
                    </button>
                </div>
            </div>
        );
    }

    if (!currentUser) {
        return <LoginScreen onLoginSuccess={handleLoginSuccess} users={users} />;
    }

    const renderView = () => {
        switch(currentView) {
            case 'Canvas': return <CanvasView tools={tools} operations={operations} assignedToolIds={assignedToolIds} handleDropToolOnOperation={handleDropToolOnOperation} handleRemoveToolFromOperation={handleRemoveToolFromOperation} handleOpenNotificationModal={handleOpenNotificationModal} userRole={currentUser.role} onShowAlert={showAlert} handleOpenRMReportModal={() => setIsRMReportModalOpen(true)} />;
            case 'Tools': return <ToolManagementView tools={tools} handleOpenToolForm={handleOpenToolForm} handleDeleteTool={handleDeleteTool} userRole={currentUser.role}/>;
            case 'Operations': return <OperationsView operations={operations} tools={tools} handleOpenOperationForm={handleOpenOperationForm} handleDeleteOperation={handleDeleteOperation} userRole={currentUser.role}/>;
            case 'Maintenance': return <MaintenanceView tools={tools} handleOpenToolForm={handleOpenToolForm} userRole={currentUser.role} />;
            case 'Personnel': return <PersonnelView personnel={personnel} courses={courses} handleOpenPersonnelForm={handleOpenPersonnelForm} handleDeletePersonnel={handleDeletePersonnel} userRole={currentUser.role} />;
            case 'Courses': return <CoursesView courses={courses} handleOpenCourseForm={handleOpenCourseForm} handleDeleteCourse={handleDeleteCourse} userRole={currentUser.role} />;
            case 'Diagrama': return <DiagramaView personnel={personnel} handleOpenPersonnelForm={handleOpenPersonnelForm} userRole={currentUser.role} />;
            case 'Vehicles': return <VehiclesView vehicles={vehicles} handleOpenVehicleForm={handleOpenVehicleForm} handleDeleteVehicle={handleDeleteVehicle} userRole={currentUser.role} />;
            case 'Settings': return <SettingsView users={users} handleOpenUserForm={handleOpenUserForm} handleDeleteUser={handleDeleteUser} userRole={currentUser.role} presentationEligibleViews={presentationEligibleViews} />;
            default: return <div>Vista no encontrada</div>;
        }
    };

    return (
        <div className="flex h-screen bg-gray-100 dark:bg-gray-900 text-gray-900 dark:text-gray-100 font-sans">
            <aside className="w-20 bg-white dark:bg-gray-800 flex flex-col items-center justify-between shadow-lg border-r border-gray-200 dark:border-gray-700 py-4">
                <nav>
                    <ul className="space-y-2">
                        {navItems.map(item => (
                             <li key={item.view}>
                                <button
                                    title={item.label}
                                    onClick={() => setCurrentView(item.view)}
                                    className={`w-14 h-14 flex items-center justify-center rounded-xl transition-all duration-300 ${currentView === item.view ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 dark:text-gray-400 hover:bg-blue-100 dark:hover:bg-gray-700'}`}
                                >
                                    <span className="text-xl">{item.icon}</span>
                                </button>
                            </li>
                        ))}
                    </ul>
                </nav>
                <div className="space-y-4">
                     <button title={isDarkMode ? 'Modo Claro' : 'Modo Oscuro'} onClick={toggleDarkMode} className="w-14 h-14 flex items-center justify-center rounded-xl text-gray-500 dark:text-gray-400 hover:bg-blue-100 dark:hover:bg-gray-700 transition-colors duration-300 text-xl"><span className="transform transition-transform duration-500 ease-in-out">{isDarkMode ? <SunIcon /> : <MoonIcon />}</span></button>
                    <button title="Cerrar Sesión" onClick={handleLogout} className="w-14 h-14 flex items-center justify-center rounded-xl text-gray-500 dark:text-gray-400 hover:bg-red-100 dark:hover:bg-red-900/50 hover:text-red-600 dark:hover:text-red-400 transition-colors duration-300 text-xl"><LogoutIcon /></button>
                </div>
            </aside>
            <main className="flex-1 flex flex-col overflow-hidden">
                <header className="bg-white dark:bg-gray-800 shadow-sm p-4 flex justify-between items-center border-b border-gray-200 dark:border-gray-700 z-10">
                    <h1 className="text-xl font-bold">{currentViewLabel}</h1>
                    <div className="flex items-center gap-6">
                        <button
                            onClick={handleRefreshData}
                            disabled={isLoading}
                            title="Actualizar Datos"
                            className="text-gray-500 dark:text-gray-400 hover:text-blue-600 dark:hover:text-blue-400 disabled:opacity-50 disabled:cursor-wait transition-colors"
                        >
                            <span className={`text-xl ${isLoading ? 'animate-spin' : ''}`}>
                                <SyncIcon />
                            </span>
                        </button>
                        <div className="flex items-center gap-2">
                            <label htmlFor="presentation-switch" className="text-sm font-medium cursor-pointer">Modo Presentación</label>
                            <div className="relative inline-block w-10 align-middle select-none transition duration-200 ease-in">
                                <input 
                                    type="checkbox" 
                                    name="presentation-switch" 
                                    id="presentation-switch" 
                                    checked={isPresentationModeActive} 
                                    onChange={togglePresentationMode}
                                    className="toggle-checkbox absolute block w-6 h-6 rounded-full bg-white border-4 appearance-none cursor-pointer"
                                />
                                <label 
                                    htmlFor="presentation-switch" 
                                    className="toggle-label block overflow-hidden h-6 rounded-full bg-gray-300 dark:bg-gray-600 cursor-pointer"
                                ></label>
                            </div>
                        </div>
                        <div className="text-right">
                           Bienvenido, <span className="font-bold">{currentUser.username}</span> ({currentUser.role})
                        </div>
                    </div>
                </header>
                <div className="flex-1 overflow-y-auto">
                    { isLoading ? 
                        <div className="flex items-center justify-center h-full"><div className="text-xl font-semibold">Cargando datos...</div></div> :
                        renderView()
                    }
                </div>
            </main>

            {/* Modals */}
            <ToolFormModal isOpen={isToolFormOpen} onClose={() => setIsToolFormOpen(false)} onSave={handleSaveTool} onDelete={handleDeleteTool} editingTool={editingTool} />
            <OperationFormModal isOpen={isOperationFormOpen} onClose={() => setIsOperationFormOpen(false)} onSave={handleSaveOperation} editingOperation={editingOperation} />
            <NotificationFormModal isOpen={isNotificationFormOpen} onClose={() => setIsNotificationFormOpen(false)} onSave={handleSaveNotification} tool={notificationTool} />
            <CourseFormModal isOpen={isCourseFormOpen} onClose={() => setIsCourseFormOpen(false)} onSave={handleSaveCourse} editingCourse={editingCourse} />
            <PersonnelFormModal isOpen={isPersonnelFormOpen} onClose={() => setIsPersonnelFormOpen(false)} onSave={handleSavePersonnel} onDelete={handleDeletePersonnel} editingPersonnel={editingPersonnel} coursesList={courses} />
            <UserFormModal isOpen={isUserFormOpen} onClose={() => setIsUserFormOpen(false)} onSave={handleSaveUser} editingUser={editingUser} />
            <VehicleFormModal isOpen={isVehicleFormOpen} onClose={() => setIsVehicleFormOpen(false)} onSave={handleSaveVehicle} editingVehicle={editingVehicle} />
            <RMReportModal isOpen={isRMReportModalOpen} onClose={() => setIsRMReportModalOpen(false)} onGenerate={handleGenerateRMReport} />


            <ConfirmModal isOpen={confirmModal.isOpen} onClose={() => setConfirmModal({ ...confirmModal, isOpen: false })} onConfirm={confirmModal.onConfirm} title={confirmModal.title} text={confirmModal.text} />
            <AlertModal isOpen={alertModal.isOpen} onClose={() => setAlertModal({ ...alertModal, isOpen: false })} title={alertModal.title} text={alertModal.text} />
        </div>
    );
};

export default App;

import React, { useState, useMemo } from 'react';
import type { Tool, Operation, Role } from '../types';
import ToolItem from '../components/ToolItem';
import OperationCard from '../components/OperationCard';
import {
    SearchIcon, PlaceholderIcon,
    ChevronLeftIcon, ChevronRightIcon,
    ClipboardListIcon
} from '../components/icons';


interface CanvasViewProps {
    tools: Tool[];
    operations: Operation[];
    assignedToolIds: Set<string>;
    handleDropToolOnOperation: (operationId: string, toolId: string) => void;
    handleRemoveToolFromOperation: (operationId: string, toolId: string) => void;
    handleOpenNotificationModal: (toolId: string) => void;
    userRole: Role | null;
    onShowAlert: (title: string, text: string) => void;
    handleOpenRMReportModal: () => void;
}

const CanvasView: React.FC<CanvasViewProps> = ({
    tools,
    operations,
    assignedToolIds,
    handleDropToolOnOperation,
    handleRemoveToolFromOperation,
    handleOpenNotificationModal,
    userRole,
    onShowAlert,
    handleOpenRMReportModal,
}) => {
    const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState('all');
    const [collapsedOperations, setCollapsedOperations] = useState<Set<string>>(new Set());

    const toggleOperationExpansion = (operationId: string) => {
        setCollapsedOperations(prev => {
            const newSet = new Set(prev);
            if (newSet.has(operationId)) {
                newSet.delete(operationId);
            } else {
                newSet.add(operationId);
            }
            return newSet;
        });
    };


    const toggleSidebar = () => setIsSidebarCollapsed(prev => !prev);

    const sortedAndFilteredTools = useMemo(() => {
        const statusOrder: { [key in Tool['status']['text']]: number } = {
            'Vencida': 1,
            'Por Vencer': 2,
            'Vigente': 3,
            'N/A': 4
        };

        return tools
            .filter(tool => {
                if (statusFilter !== 'all' && tool.status.text !== statusFilter) {
                    return false;
                }
                if (searchTerm && !(tool.herramienta.toLowerCase().includes(searchTerm.toLowerCase()) || tool.serial.toLowerCase().includes(searchTerm.toLowerCase()))) {
                    return false;
                }
                return true;
            })
            .sort((a, b) => {
                const orderA = statusOrder[a.status.text];
                const orderB = statusOrder[b.status.text];
                if (orderA !== orderB) {
                    return orderA - orderB;
                }
                // Secondary sort by next inspection date (ascending, nulls last)
                const dateA = a.nextInspectionDate?.getTime() || Infinity;
                const dateB = b.nextInspectionDate?.getTime() || Infinity;
                if (orderA === 4) return 0; // Don't sort N/A by date
                return dateA - dateB;
            });
    }, [tools, statusFilter, searchTerm]);

    return (
        <div className="flex h-full">
            {/* Left Sidebar */}
            <aside className={`relative transition-all duration-300 flex flex-col ${isSidebarCollapsed ? 'w-20' : 'w-1/3 max-w-sm'} bg-white dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700`}>
                <button 
                    onClick={toggleSidebar} 
                    className="absolute -right-4 top-8 z-20 bg-white dark:bg-gray-700 h-8 w-8 rounded-full shadow-md flex items-center justify-center border border-gray-200 dark:border-gray-600 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-600 transition-transform transform hover:scale-110"
                    aria-label={isSidebarCollapsed ? "Expand sidebar" : "Collapse sidebar"}
                >
                    {isSidebarCollapsed ? <ChevronRightIcon /> : <ChevronLeftIcon />}
                </button>

                {/* Wrapper for all sidebar content to handle visibility */}
                <div className={`flex flex-col flex-grow min-h-0 transition-opacity duration-200 ${isSidebarCollapsed ? 'opacity-0 pointer-events-none' : 'opacity-100'}`}>
                    <div className="p-4 border-b border-gray-200 dark:border-gray-700">
                        <h1 className="text-xl font-bold text-gray-700 dark:text-gray-200 whitespace-nowrap">Herramientas</h1>
                        <p className="text-sm text-gray-500 dark:text-gray-400 whitespace-nowrap">Arrastra a una operación</p>
                    </div>
                    <div className="p-4 space-y-4">
                        <div className="relative">
                            <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Buscar por nombre o serial..." className="w-full p-2 pl-10 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 dark:placeholder-gray-400" />
                            <div className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 dark:text-gray-500"><SearchIcon /></div>
                        </div>
                        <div>
                            <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} className="w-full p-2 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500">
                                <option value="all">Todas las herramientas</option>
                                <option value="Por Vencer">Por Vencer</option>
                                <option value="Vencida">Vencidas</option>
                            </select>
                        </div>
                        <div className="text-center p-2 bg-gray-100 dark:bg-gray-700/50 rounded-md">
                            <p className="text-sm font-semibold text-gray-700 dark:text-gray-200">
                                Total de Herramientas en Campo: 
                                <span className="text-blue-600 dark:text-blue-400 text-base ml-2">{assignedToolIds.size}</span>
                            </p>
                        </div>
                        <button
                            onClick={handleOpenRMReportModal}
                            className="w-full bg-indigo-600 text-white py-2 px-4 rounded-lg hover:bg-indigo-700 transition duration-300 flex items-center justify-center gap-2 text-sm font-semibold shadow-md"
                        >
                            <ClipboardListIcon />
                            <span>Generar Informe R&M</span>
                        </button>
                    </div>
                    <div className="flex-grow overflow-y-auto custom-scrollbar p-4">
                        {sortedAndFilteredTools.length > 0 ? (
                            sortedAndFilteredTools.map(tool => (
                                <ToolItem 
                                    key={tool.id} 
                                    tool={tool}
                                    isAssigned={assignedToolIds.has(tool.id)}
                                    onSelect={() => {}} 
                                    onNotificationClick={handleOpenNotificationModal}
                                    userRole={userRole}
                                    onDragAttemptFailed={onShowAlert}
                                />
                            ))
                        ) : (
                            <div className="text-center text-gray-500 dark:text-gray-400 p-8">No se encontraron herramientas.</div>
                        )}
                    </div>
                </div>
            </aside>

            {/* Right Content */}
            <main className="flex-grow p-6 overflow-y-auto custom-scrollbar">
                <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
                    {operations.length === 0 ? (
                        <div className="col-span-full flex flex-col items-center justify-center h-full text-center bg-gray-50 dark:bg-gray-800/50 rounded-lg p-8 min-h-[400px]">
                            <PlaceholderIcon />
                            <h2 className="text-2xl font-semibold text-gray-600 dark:text-gray-300">Área de Operaciones</h2>
                            <p className="text-gray-500 dark:text-gray-400 mt-2">Las operaciones se gestionan en su propia vista.</p>
                        </div>
                    ) : (
