    addSection('Equipos en inspección:', reportData.inspeccion);

    await addImageSection('WCAP Actual de R&M TRS:', reportData.wcapImage);

    addSection('Tarjetas radar a la fecha:', reportData.radarText);
    await addImageSection('', reportData.radarImage);

    doc.save(`informe_rm_${reportDate.replace(/\//g, '-')}.pdf`);
};

import React, { useState } from 'react';
import Modal from './Modal';
import { ClipboardListIcon, TimesIcon } from './icons';

interface RMReportModalProps {
    isOpen: boolean;
    onClose: () => void;
    onGenerate: (formData: any) => void;
}

const ImagePreview: React.FC<{ file: File; onRemove: () => void }> = ({ file, onRemove }) => {
    return (
        <div className="relative mt-2 p-2 border rounded-md bg-gray-50 dark:bg-gray-700/50">
            <p className="text-sm truncate">{file.name}</p>
            <button
                type="button"
                onClick={onRemove}
                className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full h-5 w-5 flex items-center justify-center text-xs"
            >
                <TimesIcon />
            </button>
        </div>
