const RMReportModal: React.FC<RMReportModalProps> = ({ isOpen, onClose, onGenerate }) => {
    const [formData, setFormData] = useState({
        novedades: '',
        reparacion: '',
        inspeccion: '',
        wcapImage: undefined as File | undefined,
        radarText: '',
        radarImage: undefined as File | undefined,
    });

    const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement | HTMLInputElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, files } = e.target;
        if (files && files.length > 0) {
            setFormData(prev => ({ ...prev, [name]: files[0] }));
        }
    };

    const removeFile = (fieldName: 'wcapImage' | 'radarImage') => {
        setFormData(prev => ({ ...prev, [fieldName]: undefined }));
        // Also clear the file input value
        const input = document.querySelector(`input[name=${fieldName}]`) as HTMLInputElement;
        if (input) {
            input.value = '';
        }
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onGenerate(formData);
    };

    return (
        <Modal isOpen={isOpen} onClose={onClose}>
            <div className="bg-white dark:bg-gray-800 p-8 rounded-xl shadow-md w-full max-w-2xl max-h-[90vh] overflow-y-auto custom-scrollbar">
                <div className="flex items-center gap-4 mb-6">
                    <div className="bg-indigo-100 dark:bg-indigo-900/50 p-3 rounded-full">
                        <ClipboardListIcon />
                    </div>
                    <h2 className="text-2xl font-bold text-gray-800 dark:text-gray-100">
                        Generar Informe Semanal R&M
                    </h2>
                </div>

                <form onSubmit={handleSubmit} className="space-y-5">
                    <div>
                        <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1">Novedades del personal</label>
                        <textarea name="novedades" value={formData.novedades} onChange={handleChange} rows={3} className="w-full p-2 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm" />
                    </div>
                    <div>
                        <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1">Equipos en reparación</label>
                        <textarea name="reparacion" value={formData.reparacion} onChange={handleChange} rows={3} className="w-full p-2 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm" />
                    </div>
                     <div>
                        <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1">Equipos en inspección</label>
                        <textarea name="inspeccion" value={formData.inspeccion} onChange={handleChange} rows={3} className="w-full p-2 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm" />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1">WCAP Actual de R&M TRS</label>
                            <input type="file" name="wcapImage" onChange={handleFileChange} accept="image/*" className="w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-indigo-50 dark:file:bg-indigo-900/50 file:text-indigo-700 dark:file:text-indigo-300 hover:file:bg-indigo-100 dark:hover:file:bg-indigo-900"/>
                            {formData.wcapImage && <ImagePreview file={formData.wcapImage} onRemove={() => removeFile('wcapImage')} />}
                        </div>
                        <div>
                            <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1">Tarjetas radar a la fecha</label>
                            <input type="text" name="radarText" value={formData.radarText} onChange={handleChange} className="w-full p-2 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm mb-2" />
                            <input type="file" name="radarImage" onChange={handleFileChange} accept="image/*" className="w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-indigo-50 dark:file:bg-indigo-900/50 file:text-indigo-700 dark:file:text-indigo-300 hover:file:bg-indigo-100 dark:hover:file:bg-indigo-900"/>
                             {formData.radarImage && <ImagePreview file={formData.radarImage} onRemove={() => removeFile('radarImage')} />}
                        </div>
                    </div>

                    <div className="flex justify-end space-x-4 pt-4 border-t border-gray-200 dark:border-gray-700 mt-6">
                        <button type="button" onClick={onClose} className="bg-gray-500 text-white py-2 px-6 rounded-lg hover:bg-gray-600 transition">Cancelar</button>
                        <button type="submit" className="bg-green-600 text-white py-2 px-6 rounded-lg hover:bg-green-700 transition">Generar PDF</button>
                    </div>
                </form>
            </div>
        </Modal>
    );
};

