    const handleGenerateRMReport = async (formData: any) => {
        try {
            setIsRMReportModalOpen(false); // Close modal immediately
            showAlert('Generando Informe', 'El informe PDF se está creando. Por favor, espera...');
            // Create maps for easy lookup
            const toolsById = tools.reduce((acc, tool) => {
                acc[tool.id] = tool;
                return acc;
            }, {} as { [id: string]: Tool });
            const personnelById = personnel.reduce((acc, p) => {
                acc[p.id] = p;
                return acc;
            }, {} as { [id: string]: Personnel });
            await generateRMReport(formData, operations, toolsById, personnelById);
            // Close the "generating" alert if it's still open
            setAlertModal(prev => ({ ...prev, isOpen: false }));
        } catch (err: any) {
            showAlert('Error al generar PDF', err.message || 'No se pudo crear el informe.');
