import type { Tool, Operation, Personnel } from '../types';

export type ReportSortOption = 'status' | 'tipo' | 'herramienta';

export const generatePDFReport = (tools: Tool[], sortBy: ReportSortOption = 'status') => {
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF();

    let toolsToReport: Tool[] = [];
    let reportTitle: string = "Informe de Inspecciones";

    const criticalTools = tools.filter(tool => tool.status.text === 'Vencida' || tool.status.text === 'Por Vencer');

    switch (sortBy) {
        case 'tipo':
            reportTitle = "Informe por Tipo (Vencidas y Por Vencer)";
            toolsToReport = [...criticalTools].sort((a, b) => {
                const typeCompare = a.tipo.localeCompare(b.tipo);
                if (typeCompare !== 0) return typeCompare;
                const toolNameCompare = a.herramienta.localeCompare(b.herramienta);
                if (toolNameCompare !== 0) return toolNameCompare;
                return a.serial.localeCompare(b.serial);
            });
            break;

        case 'herramienta':
            reportTitle = "Informe por Nombre (Vencidas y Por Vencer)";
            toolsToReport = [...criticalTools].sort((a, b) => {
                const toolNameCompare = a.herramienta.localeCompare(b.herramienta);
                if (toolNameCompare !== 0) return toolNameCompare;
                return a.serial.localeCompare(b.serial);
            });
            break;

        case 'status':
        default:
            reportTitle = "Informe de Herramientas Vencidas y Por Vencer";
            toolsToReport = criticalTools;
            const statusOrder: { [key: string]: number } = { 'Vencida': 1, 'Por Vencer': 2 };
            toolsToReport.sort((a, b) => {
                const orderA = statusOrder[a.status.text] || 3;
                const orderB = statusOrder[b.status.text] || 3;
                if (orderA !== orderB) return orderA - orderB;
                const dateA = a.nextInspectionDate?.getTime() || 0;
                const dateB = b.nextInspectionDate?.getTime() || 0;
                return dateA - dateB;
            });
            break;
    }

    if (toolsToReport.length === 0) {
        alert("No hay herramientas para incluir en este tipo de informe.");
        return;
    }

    const tableColumn = ["Herramienta", "Serial", "Estado", "Fecha de Vencimiento"];
    const tableRows = toolsToReport.map(tool => [
        `${tool.herramienta} ${tool.detalle || ''}`.trim(),
        tool.serial,
        tool.status.text,
        tool.nextInspectionDate ? tool.nextInspectionDate.toLocaleDateString('es-ES') : 'N/A'
    ]);

    const reportDate = new Date().toLocaleDateString('es-ES');

    // Using declare to assert the type of autoTable
    (doc as any).autoTable({ 
        head: [tableColumn], 
        body: tableRows, 
        startY: 35,
        margin: { top: 35 }, // Ensures header margin is applied to all pages
        theme: 'grid', 
        headStyles: { fillColor: [22, 160, 133] },
        didDrawPage: (data: any) => {
            // Header for every page
            doc.setFontSize(11);
            doc.setTextColor(100);
            doc.text(`Fecha: ${reportDate}`, 14, 15);

            doc.setFontSize(18);
            doc.setTextColor(0);
            doc.setFont('helvetica', 'bold');
            doc.text(reportTitle, 14, 25);

            // Optional: Footer with page number
            const str = "Página " + doc.internal.getNumberOfPages();
            doc.setFontSize(10);
            doc.setTextColor(150);
            const pageSize = doc.internal.pageSize;
            const pageHeight = pageSize.height ? pageSize.height : pageSize.getHeight();
            doc.text(str, data.settings.margin.left, pageHeight - 10);
        }
    });

    const safeTitle = reportTitle.replace(/ /g, '_').toLowerCase();
    doc.save(`${safeTitle}_${reportDate.replace(/\//g, '-')}.pdf`);
};

const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = error => reject(error);
    });
};

export const generateRMReport = async (
    reportData: {
        novedades: string;
        reparacion: string;
        inspeccion: string;
        wcapPercentages: { [personnelId: string]: string };
        radarText: string;
        radarImage?: File;
    },
    operations: Operation[],
    toolsById: { [id: string]: Tool },
    personnelById: { [id: string]: Personnel }
) => {
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF('p', 'mm', 'a4');
    const reportDate = new Date().toLocaleDateString('es-ES');
    const pageHeight = doc.internal.pageSize.height;
    const margin = 14;
    let pageCount = 1;
    let yPosition = 50;

    const addHeaderAndFooter = (pageNumber: number) => {
        doc.setFontSize(11);
        doc.setTextColor(100);
        doc.text(`Fecha: ${reportDate}`, margin, 15);

        doc.setFontSize(18);
        doc.setTextColor(0);
        doc.setFont('helvetica', 'bold');
        doc.text("Informe Semanal R&M", margin, 25);

        const str = "Página " + pageNumber;
        doc.setFontSize(10);
        doc.setTextColor(150);
        doc.text(str, margin, pageHeight - 10);
    };

    const checkNewPage = (requiredHeight: number) => {
        if (yPosition + requiredHeight > pageHeight - 20) {
            doc.addPage();
            pageCount++;
            addHeaderAndFooter(pageCount);
            yPosition = 40;
        }
    };

    addHeaderAndFooter(pageCount);

    doc.setFontSize(16);
    doc.setFont('helvetica', 'bold');
    doc.text("Detalle por Equipo", margin, 40);

    for (const op of operations) {
        const assignedTools = op.assignedTools.map(id => toolsById[id]).filter(Boolean);
        const toolNames = assignedTools.length > 0 ? assignedTools.map(t => t.herramienta).join(', ') : 'Ninguna';
        const splitToolList = doc.splitTextToSize(`- Herramientas Asignadas: ${toolNames}`, 180);
        const sectionHeight = 25 + (splitToolList.length * 5);

        checkNewPage(sectionHeight);

        doc.setFontSize(12);
        doc.setFont('helvetica', 'bold');
        doc.text(`EQUIPO: ${op.equipo}`, margin, yPosition);
        yPosition += 7;

        doc.setFontSize(10);
        doc.setFont('helvetica', 'normal');

        doc.text(splitToolList, margin + 2, yPosition);
        yPosition += (splitToolList.length * 5);

        let fechaText = 'N/A';
        if (op.estado === 'Programada' && op.fechaInicio) {
            fechaText = `Inicio: ${op.fechaInicio}`;
        } else if (op.fechaInicio) {
            fechaText = `${op.fechaInicio}${op.fechaFin ? ' al ' + op.fechaFin : ''}`;
        }

        const opDetails = [
            `- Cantidad de Herramientas: ${op.assignedTools.length}`,
            `- Operadora: ${op.operadora}`,
            `- Pozo: ${op.yacimiento}`,
            `- Estado: ${op.estado}`,
            `- Fecha: ${fechaText}`,
        ];
        doc.text(opDetails, margin + 2, yPosition);
        yPosition += (opDetails.length * 5) + 5;
    }

    doc.addPage();
    pageCount++;
    addHeaderAndFooter(pageCount);
    yPosition = 40;

    const addSection = (title: string, content: string) => {
        if (!content || content.trim() === '') return;
        const splitContent = doc.splitTextToSize(content, 180);
        const sectionHeight = 8 + (splitContent.length * 5) + 10;
        checkNewPage(sectionHeight);
        doc.setFontSize(14);
        doc.setFont('helvetica', 'bold');
        doc.text(title, margin, yPosition);
        yPosition += 8;
        doc.setFontSize(10);
        doc.setFont('helvetica', 'normal');
        doc.text(splitContent, margin, yPosition);
        yPosition += (splitContent.length * 5) + 10;
    };

    const addWCAPSection = (
        title: string, 
        percentages: { [personnelId: string]: string }, 
        personnelMap: { [id: string]: Personnel }
    ) => {
        const personnelWithPercentage = Object.entries(percentages)
            .filter(([, percentage]) => percentage && percentage.trim() !== '')
            .map(([id, percentage]) => ({ person: personnelMap[id], percentage }));

        if (personnelWithPercentage.length === 0) return;

        checkNewPage(20);

        doc.setFontSize(14);
        doc.setFont('helvetica', 'bold');
        doc.text(title, margin, yPosition);
        yPosition += 10;

        const cardWidth = 90;
        const cardHeight = 25;
        const cardMargin = 5;
        let xPosition = margin;

        for (const item of personnelWithPercentage) {
            if (!item.person) continue;

            checkNewPage(cardHeight + cardMargin);

            const avatarX = xPosition + 10;
            const avatarY = yPosition + 10;
            const textX = xPosition + 25;

            doc.setFillColor(230, 230, 230);
            doc.circle(avatarX, avatarY, 8, 'F');

            doc.setFontSize(8);
            doc.setFont('helvetica', 'bold');
            doc.text(`${item.percentage}%`, avatarX, avatarY + 12, { align: 'center' });

            doc.setFontSize(10);
            doc.setFont('helvetica', 'bold');
            doc.text(`${item.person.lastName.toUpperCase()}, ${item.person.firstName.toUpperCase()}`, textX, avatarY - 2);

            doc.setFontSize(9);
            doc.setFont('helvetica', 'normal');
            doc.setTextColor(150);
            doc.text(item.person.sector, textX, avatarY + 3);

            doc.setTextColor(0);

            if (xPosition === margin) {
                xPosition += cardWidth + cardMargin;
            } else {
                xPosition = margin;
                yPosition += cardHeight + cardMargin;
            }
        }
        if (xPosition !== margin) {
             yPosition += cardHeight + cardMargin;
        }
    };


    const addImageSection = async (title: string, imageFile?: File) => {
        if (!imageFile) return;
        const base64Image = await fileToBase64(imageFile);
        const imgProps = doc.getImageProperties(base64Image);
        const imgWidth = 160;
        const imgHeight = (imgProps.height * imgWidth) / imgProps.width;
        const sectionHeight = (title ? 10 : 0) + imgHeight + 10;

        checkNewPage(sectionHeight);

        if (title) {
            doc.setFontSize(14);
            doc.setFont('helvetica', 'bold');
            doc.text(title, margin, yPosition);
            yPosition += 10;
        }
        doc.addImage(base64Image, 'JPEG', margin, yPosition, imgWidth, imgHeight);
        yPosition += imgHeight + 10;
    };

    addSection('Novedades del personal:', reportData.novedades);
    addSection('Equipos en reparación:', reportData.reparacion);
    addSection('Equipos en inspección:', reportData.inspeccion);

    addWCAPSection('WCAP Actual de R&M TRS:', reportData.wcapPercentages, personnelById);

    addSection('Tarjetas radar a la fecha:', reportData.radarText);
    await addImageSection('', reportData.radarImage);

    doc.save(`informe_rm_${reportDate.replace(/\//g, '-')}.pdf`);
};

import React, { useState, useMemo } from 'react';
