import React, { useState, useMemo, useEffect } from 'react';
import type { Tool, Role } from '../types';
import { generatePDFReport, ReportSortOption } from '../services/reportService';
import { PlusIcon, PencilIcon, TrashIcon, PdfIcon, SearchIcon, ChevronDownIcon, ChevronRightIcon, ArrowsExpandIcon, ArrowsCollapseIcon } from '../components/icons';
import Modal from '../components/Modal';

interface ToolManagementViewProps {
    tools: Tool[];
    handleOpenToolForm: (tool: Tool | null) => void;
    handleDeleteTool: (toolId: string) => void;
    userRole: Role | null;
}

const ToolManagementView: React.FC<ToolManagementViewProps> = ({ tools, handleOpenToolForm, handleDeleteTool, userRole }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());
    const [isReportModalOpen, setIsReportModalOpen] = useState(false);

    const filteredTools = useMemo(() => {
        if (!searchTerm) {
            return tools;
        }
        return tools.filter(tool =>
            tool.serial.toLowerCase().includes(searchTerm.toLowerCase()) ||
            tool.herramienta.toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [tools, searchTerm]);

    const groupedTools = useMemo(() => {
        const groups: { [key: string]: Tool[] } = {};
        filteredTools.forEach(tool => {
            const key = tool.herramienta;
            if (!groups[key]) {
                groups[key] = [];
            }
            groups[key].push(tool);
        });

        return Object.keys(groups).sort().reduce((obj, key) => {
            obj[key] = groups[key];
            return obj;
        }, {} as { [key: string]: Tool[] });
    }, [filteredTools]);

    useEffect(() => {
        if (searchTerm) {
            setExpandedGroups(new Set(Object.keys(groupedTools)));
        }
    }, [searchTerm, groupedTools]);

    const toggleGroup = (groupName: string) => {
        setExpandedGroups(prev => {
            const next = new Set(prev);
            if (next.has(groupName)) {
                next.delete(groupName);
            } else {
                next.add(groupName);
            }
            return next;
        });
    };

    const handleExpandAll = () => {
        setExpandedGroups(new Set(Object.keys(groupedTools)));
    };

    const handleCollapseAll = () => {
        setExpandedGroups(new Set());
    };

    const handleGenerateReport = (sortBy: ReportSortOption) => {
        generatePDFReport(tools, sortBy);
        setIsReportModalOpen(false);
    };

    const getStatusChipClass = (status: Tool['status']) => {
        switch(status.color) {
            case 'green': return 'bg-green-100 text-green-800 dark:bg-green-900/40 dark:text-green-300';
            case 'yellow': return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/40 dark:text-yellow-300';
            case 'red': return 'bg-red-100 text-red-800 dark:bg-red-900/40 dark:text-red-300';
            default: return 'bg-gray-100 text-gray-800 dark:bg-gray-600 dark:text-gray-200';
        }
    };

    const formatDate = (dateString: string) => {
        if (!dateString) return 'N/A';
        try {
            const [year, month, day] = dateString.split('-');
            if (!year || !month || !day) return dateString;
            return `${day}/${month}/${year}`;
        } catch (e) {
            return dateString;
        }
    };

    const getGroupSummary = (groupTools: Tool[]) => {
        const total = groupTools.length;
        const expired = groupTools.filter(t => t.status.text === 'Vencida').length;
        const expiring = groupTools.filter(t => t.status.text === 'Por Vencer').length;

        return { total, expired, expiring };
    };

    return (
        <div className="h-full flex flex-col bg-gray-100 dark:bg-gray-900">
            <header className="sticky top-0 z-10 bg-gray-100 dark:bg-gray-900 flex flex-col md:flex-row justify-between md:items-center gap-4 px-6 md:px-8 py-4 border-b border-gray-200 dark:border-gray-700 shadow-sm">
                <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Gestión de Herramientas</h1>
                <div className="flex items-center gap-4">
                    <div className="relative">
                        <input
                            type="text"
                            value={searchTerm}
                            onChange={e => setSearchTerm(e.target.value)}
                            placeholder="Buscar por serial o nombre..."
                            className="w-full p-2 pl-10 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 text-gray-900 dark:text-white dark:placeholder-gray-400"
                        />
                        <div className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 dark:text-gray-500"><SearchIcon /></div>
                    </div>
                    <button onClick={handleExpandAll} title="Expandir Todo" className="p-2 text-gray-600 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm hover:bg-gray-100 dark:hover:bg-gray-600 transition">
                        <ArrowsExpandIcon />
                    </button>
                    <button onClick={handleCollapseAll} title="Contraer Todo" className="p-2 text-gray-600 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm hover:bg-gray-100 dark:hover:bg-gray-600 transition">
                        <ArrowsCollapseIcon />
                    </button>
                    <button 
                        onClick={() => setIsReportModalOpen(true)}
                        title="Generar Informe PDF"
                        className="bg-green-600 text-white py-2 px-4 rounded-lg hover:bg-green-700 transition duration-300 flex items-center justify-center gap-2 text-sm font-semibold shadow-md">
                        <PdfIcon /> <span>Generar Informe</span>
                    </button>
                    <button 
                        onClick={() => handleOpenToolForm(null)} 
                        className="bg-blue-600 text-white py-2 px-4 rounded-lg hover:bg-blue-700 transition duration-300 flex items-center justify-center gap-2 text-sm font-semibold shadow-md disabled:bg-gray-400 disabled:cursor-not-allowed"
                        disabled={userRole !== 'Admin'}
                    >
                        <PlusIcon /> <span>Nueva Herramienta</span>
                    </button>
                </div>
            </header>

            <div className="flex-grow overflow-y-auto custom-scrollbar p-6 md:p-8">
                <div className="space-y-4">
                    {Object.keys(groupedTools).length > 0 ? (
                        Object.entries(groupedTools).map(([groupName, groupTools]: [string, Tool[]]) => {
                            const isExpanded = expandedGroups.has(groupName);
                            const summary = getGroupSummary(groupTools);

                            return (
                                <div key={groupName} className="bg-white dark:bg-gray-800 rounded-lg shadow-md overflow-hidden border border-gray-200 dark:border-gray-700">
                                    <button 
                                        onClick={() => toggleGroup(groupName)}
                                        className="w-full flex items-center justify-between p-4 cursor-pointer bg-gray-50 dark:bg-gray-700 hover:bg-gray-100 dark:hover:bg-gray-600 transition-colors select-none text-left focus:outline-none focus:ring-2 focus:ring-inset focus:ring-blue-500"
                                    >
                                        <div className="flex items-center gap-3">
                                            <div className="text-gray-500 dark:text-gray-400">
                                                {isExpanded ? <ChevronDownIcon /> : <ChevronRightIcon />}
                                            </div>
                                            <h3 className="text-lg font-bold text-gray-800 dark:text-white">{groupName}</h3>
                                            <span className="bg-gray-200 dark:bg-gray-600 text-gray-700 dark:text-gray-100 text-xs px-2 py-0.5 rounded-full font-mono font-bold">
                                                {summary.total}
                                            </span>
                                        </div>
                                        <div className="flex gap-2 text-sm">
                                            {summary.expired > 0 && (
                                                <span className="text-red-700 dark:text-red-300 font-bold bg-red-100 dark:bg-red-900/40 px-2 py-0.5 rounded border border-red-200 dark:border-red-800">
                                                    {summary.expired} Vencida{summary.expired > 1 ? 's' : ''}
                                                </span>
                                            )}
                                            {summary.expiring > 0 && (
                                                <span className="text-yellow-700 dark:text-yellow-300 font-bold bg-yellow-100 dark:bg-yellow-900/40 px-2 py-0.5 rounded border border-yellow-200 dark:border-yellow-800">
                                                    {summary.expiring} Por Vencer
                                                </span>
                                            )}
                                            {summary.expired === 0 && summary.expiring === 0 && (
                                                <span className="text-green-600 dark:text-green-400 font-bold flex items-center gap-1">
                                                    <i className="fas fa-check-circle"></i> OK
                                                </span>
                                            )}
                                        </div>
                                    </button>

                                    {isExpanded && (
                                        <div className="overflow-x-auto border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
                                            <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
                                                <thead className="bg-gray-100 dark:bg-gray-900">
                                                    <tr>
                                                        <th scope="col" className="px-6 py-3 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Detalle / Tipo</th>
                                                        <th scope="col" className="px-6 py-3 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Serial</th>
                                                        <th scope="col" className="px-6 py-3 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Última Insp.</th>
                                                        <th scope="col" className="px-6 py-3 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Próxima Insp.</th>
                                                        <th scope="col" className="px-6 py-3 text-center text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Días</th>
                                                        <th scope="col" className="px-6 py-3 text-center text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Estado</th>
                                                        <th scope="col" className="px-6 py-3 text-right text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wider">Acciones</th>
                                                    </tr>
                                                </thead>
                                                <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
                                                    {groupTools.map(tool => (
                                                        <tr key={tool.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                                            <td className="px-6 py-4 whitespace-nowrap">
                                                                <div className="text-sm font-semibold text-gray-900 dark:text-gray-100">{tool.detalle || '-'}</div>
                                                                <div className="text-xs text-gray-500 dark:text-gray-400">{tool.tipo}</div>
                                                            </td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600 dark:text-gray-300 font-mono">{tool.serial}</td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600 dark:text-gray-300">{formatDate(tool.ultimaInspeccion)}</td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600 dark:text-gray-300">
                                                                {tool.nextInspectionDate ? tool.nextInspectionDate.toLocaleDateString('es-ES', { day: '2-digit', month: '2-digit', year: 'numeric'}) : 'N/A'}
                                                            </td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-center text-sm font-bold">
                                                                {tool.status.text === 'Por Vencer' && tool.daysUntilExpiry !== null && tool.daysUntilExpiry !== undefined ? (
                                                                    <span className="text-yellow-600 dark:text-yellow-400">{tool.daysUntilExpiry}</span>
                                                                ) : (
                                                                    <span className="text-gray-400 dark:text-gray-600">-</span>
                                                                )}
                                                            </td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-center">
                                                                <span className={`px-3 py-1 inline-flex text-xs leading-5 font-bold rounded-full border ${getStatusChipClass(tool.status)}`}>
                                                                    {tool.status.text}
                                                                </span>
                                                            </td>
                                                            <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                                                                <button onClick={() => handleOpenToolForm(tool)} className="text-indigo-600 hover:text-indigo-900 dark:text-indigo-400 dark:hover:text-indigo-300 mr-4 disabled:opacity-50 disabled:cursor-not-allowed" title="Editar" disabled={userRole !== 'Admin'}><PencilIcon /></button>
                                                                <button onClick={() => handleDeleteTool(tool.id)} className="text-red-600 hover:text-red-900 dark:text-red-400 dark:hover:text-red-300 disabled:opacity-50 disabled:cursor-not-allowed" title="Eliminar" disabled={userRole !== 'Admin'}><TrashIcon /></button>
                                                            </td>
                                                        </tr>
                                                    ))}
                                                </tbody>
                                            </table>
                                        </div>
                                    )}
                                </div>
                            );
                        })
                    ) : (
                        <div className="text-center text-gray-500 dark:text-gray-400 p-8 bg-white dark:bg-gray-800 rounded-lg shadow-md border border-gray-200 dark:border-gray-700">
                            {searchTerm ? 'No se encontraron herramientas que coincidan con la búsqueda.' : 'No hay herramientas cargadas en el sistema.'}
                        </div>
                    )}
                </div>
            </div>

            <Modal isOpen={isReportModalOpen} onClose={() => setIsReportModalOpen(false)}>
                <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-md w-full max-w-md">
                    <h2 className="text-xl font-bold mb-6 text-gray-800 dark:text-gray-100">Opciones de Informe PDF</h2>
                    <div className="space-y-3">
                        <button
                            onClick={() => handleGenerateReport('status')}
                            className="w-full text-left p-4 bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 rounded-lg transition border border-gray-200 dark:border-gray-600"
                        >
                            <p className="font-semibold text-gray-800 dark:text-gray-100">Por Estado (Prioridad)</p>
                            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">Informe acotado. Incluye solo herramientas vencidas y por vencer, ordenadas por urgencia.</p>
                        </button>
                        <button
                            onClick={() => handleGenerateReport('tipo')}
                            className="w-full text-left p-4 bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 rounded-lg transition border border-gray-200 dark:border-gray-600"
                        >
                            <p className="font-semibold text-gray-800 dark:text-gray-100">Por Tipo de Herramienta</p>
                            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">Informe acotado. Incluye solo herramientas vencidas y por vencer, agrupadas por tipo.</p>
                        </button>
                        <button
                            onClick={() => handleGenerateReport('herramienta')}
                            className="w-full text-left p-4 bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 rounded-lg transition border border-gray-200 dark:border-gray-600"
                        >
                            <p className="font-semibold text-gray-800 dark:text-gray-100">Por Nombre de Herramienta</p>
                            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">Informe acotado. Incluye solo herramientas vencidas y por vencer, ordenadas alfabéticamente por nombre.</p>
                        </button>
                    </div>
                    <div className="mt-8 flex justify-end">
                        <button onClick={() => setIsReportModalOpen(false)} className="bg-gray-500 text-white py-2 px-6 rounded-lg hover:bg-gray-600 transition">Cancelar</button>
                    </div>
                </div>
            </Modal>
        </div>
    );
};

