import React, { useMemo } from 'react';
import Modal from './Modal';
import type { Tool } from '../types';

interface InspectionTimelineModalProps {
    isOpen: boolean;
    onClose: () => void;
    tools: Tool[];
}

const InspectionTimelineModal: React.FC<InspectionTimelineModalProps> = ({ isOpen, onClose, tools }) => {
    const timelineData = useMemo(() => {
        // Filtrar solo herramientas que tienen fecha de inspección
        const toolsWithDate = tools.filter(t => t.ultimaInspeccion);

        // Ordenar por fecha descendente
        const sorted = [...toolsWithDate].sort((a, b) => 
            new Date(b.ultimaInspeccion).getTime() - new Date(a.ultimaInspeccion).getTime()
        );

        // Agrupar por Mes Año
        const grouped: { [key: string]: Tool[] } = {};
        sorted.forEach(tool => {
            const date = new Date(tool.ultimaInspeccion + 'T00:00:00');
            const key = date.toLocaleString('es-ES', { month: 'long', year: 'numeric' });
            if (!grouped[key]) grouped[key] = [];
            grouped[key].push(tool);
        });

        return Object.entries(grouped);
    }, [tools]);

    const formatDate = (dateStr: string) => {
        const [year, month, day] = dateStr.split('-');
        return `${day}/${month}/${year}`;
    };

    return (
        <Modal isOpen={isOpen} onClose={onClose}>
            <div className="bg-white dark:bg-gray-800 p-8 rounded-xl shadow-md w-full max-w-3xl max-h-[85vh] flex flex-col">
                <h2 className="text-2xl font-bold mb-6 text-gray-800 dark:text-gray-100 flex items-center gap-3">
                    <i className="fas fa-history text-blue-500"></i>
                    Historial de Inspecciones (Línea de Tiempo)
                </h2>

                <div className="flex-grow overflow-y-auto custom-scrollbar pr-4">
                    {timelineData.length > 0 ? (
                        <div className="relative border-l-2 border-blue-200 dark:border-blue-900 ml-3 py-2">
                            {timelineData.map(([monthYear, monthTools]) => (
                                <div key={monthYear} className="mb-10 last:mb-0">
                                    {/* Month Header */}
                                    <div className="absolute -left-[9px] mt-1 h-4 w-4 rounded-full bg-blue-500 border-4 border-white dark:border-gray-800"></div>
                                    <h3 className="text-lg font-bold text-blue-600 dark:text-blue-400 capitalize mb-4 ml-6">
                                        {monthYear}
                                    </h3>

                                    {/* Tool Cards for that month */}
                                    <div className="ml-6 space-y-3">
                                        {monthTools.map(tool => (
                                            <div key={`${tool.id}-${tool.ultimaInspeccion}`} className="bg-gray-50 dark:bg-gray-700/50 p-4 rounded-lg border border-gray-100 dark:border-gray-700 shadow-sm hover:shadow-md transition-shadow">
                                                <div className="flex justify-between items-start">
                                                    <div>
                                                        <div className="flex items-center gap-2 mb-1">
                                                            <span className="text-xs font-bold uppercase tracking-wider px-2 py-0.5 rounded bg-gray-200 dark:bg-gray-600 text-gray-700 dark:text-gray-300">
                                                                {tool.tipo}
                                                            </span>
                                                            {tool.tipoUltimaInspeccion && (
                                                                <span className={`text-xs font-bold px-2 py-0.5 rounded ${
                                                                    tool.tipoUltimaInspeccion === 'Full' 
                                                                    ? 'bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-300' 
                                                                    : 'bg-indigo-100 text-indigo-700 dark:bg-indigo-900/40 dark:text-indigo-300'
                                                                }`}>
                                                                    {tool.tipoUltimaInspeccion}
                                                                </span>
                                                            )}
                                                        </div>
                                                        <h4 className="font-bold text-gray-900 dark:text-white">{tool.herramienta}</h4>
                                                        <p className="text-sm text-gray-500 dark:text-gray-400 font-mono">Serial: {tool.serial}</p>
                                                    </div>
                                                    <div className="text-right">
                                                        <p className="text-sm font-bold text-gray-700 dark:text-gray-200">{formatDate(tool.ultimaInspeccion)}</p>
                                                        <p className="text-xs text-gray-500 dark:text-gray-500">Fecha de inspección</p>
                                                    </div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="text-center py-20 text-gray-500 dark:text-gray-400">
                            <i className="fas fa-calendar-times text-5xl mb-4 opacity-20"></i>
                            <p>No hay registros de inspección para mostrar.</p>
                        </div>
                    )}
                </div>

                <div className="mt-8 flex justify-end">
                    <button 
                        onClick={onClose} 
                        className="bg-gray-500 text-white py-2 px-8 rounded-lg hover:bg-gray-600 transition shadow-md"
                    >
                        Cerrar
                    </button>
                </div>
            </div>
        </Modal>
    );
};

